export const MCP_API_BASE_PLACEHOLDER = "__MCP_API_BASE__"
export const MCP_DOCS_NAV_HTML = "<li><a href=\"#mcp-visao-geral\" :class=\"ativo('mcp-visao-geral')\" x-show=\"bate('Visão geral MCP: como funciona como funciona oauth pkce token sessão papéis ponte whatsapp')\">Visão geral</a></li>\n<li><a href=\"#mcp-conectar\" :class=\"ativo('mcp-conectar')\" x-show=\"bate('Conectar um cliente Conectar um cliente de IA ao MCP conectar compatibilidade clientes tabela')\">Conectar um cliente</a></li>\n<li><a href=\"#mcp-cliente-claude-code\" :class=\"ativo('mcp-cliente-claude-code')\" x-show=\"bate('Guia: Claude Code Claude Code')\">Guia: Claude Code</a></li>\n<li><a href=\"#mcp-cliente-claude-ai-desktop\" :class=\"ativo('mcp-cliente-claude-ai-desktop')\" x-show=\"bate('Guia: claude.ai e Desktop claude.ai e Claude Desktop')\">Guia: claude.ai e Desktop</a></li>\n<li><a href=\"#mcp-cliente-codex\" :class=\"ativo('mcp-cliente-codex')\" x-show=\"bate('Guia: Codex (OpenAI) OpenAI Codex (CLI e extensão para IDE)')\">Guia: Codex (OpenAI)</a></li>\n<li><a href=\"#mcp-cliente-cursor\" :class=\"ativo('mcp-cliente-cursor')\" x-show=\"bate('Guia: Cursor Cursor')\">Guia: Cursor</a></li>\n<li><a href=\"#mcp-cliente-vscode\" :class=\"ativo('mcp-cliente-vscode')\" x-show=\"bate('Guia: VS Code (Copilot) VS Code (GitHub Copilot)')\">Guia: VS Code (Copilot)</a></li>\n<li><a href=\"#mcp-cliente-windsurf\" :class=\"ativo('mcp-cliente-windsurf')\" x-show=\"bate('Guia: Windsurf Windsurf (Cascade)')\">Guia: Windsurf</a></li>\n<li><a href=\"#mcp-cliente-gemini-cli\" :class=\"ativo('mcp-cliente-gemini-cli')\" x-show=\"bate('Guia: Gemini CLI Gemini CLI')\">Guia: Gemini CLI</a></li>\n<li><a href=\"#mcp-cliente-cline\" :class=\"ativo('mcp-cliente-cline')\" x-show=\"bate('Guia: Cline Cline')\">Guia: Cline</a></li>\n<li><a href=\"#mcp-cliente-zed\" :class=\"ativo('mcp-cliente-zed')\" x-show=\"bate('Guia: Zed Zed')\">Guia: Zed</a></li>\n<li><a href=\"#mcp-cliente-continue\" :class=\"ativo('mcp-cliente-continue')\" x-show=\"bate('Guia: Continue Continue')\">Guia: Continue</a></li>\n<li><a href=\"#mcp-cliente-chatgpt\" :class=\"ativo('mcp-cliente-chatgpt')\" x-show=\"bate('Guia: ChatGPT ChatGPT (modo desenvolvedor)')\">Guia: ChatGPT</a></li>\n<li><a href=\"#mcp-cliente-mcp-remote\" :class=\"ativo('mcp-cliente-mcp-remote')\" x-show=\"bate('Guia: mcp-remote Ponte mcp-remote (clientes só com stdio ou sem DCR)')\">Guia: mcp-remote</a></li>\n<li><a href=\"#mcp-ferramentas\" :class=\"ativo('mcp-ferramentas')\" x-show=\"bate('Ferramentas (30 tools) Referência das tools do MCP tools ferramentas parâmetros destrutivas confirm')\">Ferramentas (30 tools)</a></li>\n<li><a href=\"#mcp-seguranca\" :class=\"ativo('mcp-seguranca')\" x-show=\"bate('Segurança Segurança do MCP')\">Segurança</a></li>\n<li><a href=\"#mcp-problemas\" :class=\"ativo('mcp-problemas')\" x-show=\"bate('Solução de problemas Solução de problemas do MCP erro login sessão expirada 401 429')\">Solução de problemas</a></li>\n<li><a href=\"#mcp-exemplos\" :class=\"ativo('mcp-exemplos')\" x-show=\"bate('Exemplos de uso Exemplos de uso')\">Exemplos de uso</a></li>"
export const MCP_DOCS_HTML = "<div class=\"card mcp-doc\" id=\"mcp-visao-geral\" x-show=\"bate($el.textContent)\">\n<h2>MCP: como funciona</h2>\n<p>O Api-WhatsApp-MCP traz um <strong>servidor MCP remoto</strong> (Model Context Protocol) dentro do mesmo processo da API. Um assistente de IA compatível com MCP remoto se autentica no navegador com a conta do próprio usuário e passa a operar instâncias, enviar mensagens, ler respostas e consultar métricas, sempre restrito àquela conta.</p>\n<p>Para conectar um cliente específico (Claude Code, Codex, Cursor e outros), vá direto para <a href=\"#mcp-conectar\">Conectar um cliente</a>. A referência das 30 tools está em <a href=\"#mcp-ferramentas\">Ferramentas (30 tools)</a>.</p>\n<h3 id=\"mcp-visao-geral-visão-geral\" style=\"margin-top:20px\">Visão geral</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Item</th>\n<th>Valor</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Endpoint</td>\n<td><code>POST https://&lt;seu-dominio&gt;/mcp</code></td>\n</tr>\n<tr>\n<td>Transporte</td>\n<td>Streamable HTTP, <strong>sem estado</strong> (um <code>McpServer</code> novo por requisição; não há sessão MCP entre chamadas)</td>\n</tr>\n<tr>\n<td>Autenticação</td>\n<td>OAuth 2.1, Authorization Code com <strong>PKCE S256</strong>, cliente público registrado por Dynamic Client Registration (DCR)</td>\n</tr>\n<tr>\n<td>Token de acesso</td>\n<td>O <strong>mesmo JWT</strong> do painel (mesma sessão, mesmo tempo de inatividade)</td>\n</tr>\n<tr>\n<td>Escopo</td>\n<td>Cada tool chama a rota REST equivalente dentro do processo, com o JWT do usuário. Isolamento por conta, papéis e anti-flood valem exatamente como na API</td>\n</tr>\n<tr>\n<td>Tools</td>\n<td>30 (ver <a href=\"#mcp-ferramentas\">Ferramentas (30 tools)</a>)</td>\n</tr>\n</tbody></table>\n<p>Somente <code>POST /mcp</code> existe. Um <code>GET /mcp</code> ou <code>DELETE /mcp</code> responde 404, o que é compatível com o modo sem estado.</p>\n<h3 id=\"mcp-visao-geral-arquitetura\" style=\"margin-top:20px\">Arquitetura</h3>\n<p class=\"muted\">Diagrama disponível na documentação do repositório (docs/mcp/overview.md).</p>\n<p>Pontos importantes do desenho:</p>\n<ul>\n<li><strong>Nenhuma regra de negócio é duplicada.</strong> Cada tool só traduz parâmetros e chama a rota REST com <code>app.inject()</code> (chamada em processo, sem rede). Por isso qualquer regra de autenticação, escopo por conta, papel (OWNER, MEMBER, SUPER_ADMIN) ou anti-flood vale automaticamente no MCP.</li>\n<li><strong>Sem estado.</strong> Cada requisição cria um servidor MCP novo, registra as tools e responde. Não há sessão MCP para expirar nem para sincronizar entre réplicas.</li>\n<li><strong>O erro da rota é o erro da tool.</strong> A tool devolve um JSON com <code>statusCode</code> e <code>body</code> da rota REST, então <code>401</code>, <code>403</code>, <code>404</code> e <code>429</code> chegam ao modelo com o significado de sempre.</li>\n</ul>\n<h3 id=\"mcp-visao-geral-descoberta-e-autenticação-oauth\" style=\"margin-top:20px\">Descoberta e autenticação OAuth</h3>\n<h4 id=\"mcp-visao-geral-endpoints\" style=\"margin-top:20px\">Endpoints</h4>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Endpoint</th>\n<th>Função</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>GET /.well-known/oauth-protected-resource</code> e <code>GET /.well-known/oauth-protected-resource/mcp</code></td>\n<td>Metadados do recurso protegido: <code>resource</code> (<code>&lt;issuer&gt;/mcp</code>) e <code>authorization_servers</code></td>\n</tr>\n<tr>\n<td><code>GET /.well-known/oauth-authorization-server</code></td>\n<td>Metadados do servidor de autorização: <code>issuer</code>, <code>authorization_endpoint</code>, <code>token_endpoint</code>, <code>registration_endpoint</code>, <code>code_challenge_methods_supported: [&quot;S256&quot;]</code>, <code>grant_types_supported: [&quot;authorization_code&quot;]</code>, <code>token_endpoint_auth_methods_supported: [&quot;none&quot;]</code></td>\n</tr>\n<tr>\n<td><code>POST /mcp/oauth/register</code></td>\n<td>Dynamic Client Registration (RFC 7591), cliente público sem segredo</td>\n</tr>\n<tr>\n<td><code>GET /mcp/oauth/authorize</code></td>\n<td>Mostra o formulário de login</td>\n</tr>\n<tr>\n<td><code>POST /mcp/oauth/authorize</code></td>\n<td>Valida e-mail e senha e emite o código de autorização</td>\n</tr>\n<tr>\n<td><code>POST /mcp/oauth/token</code></td>\n<td>Troca <code>code</code> + <code>code_verifier</code> pelo JWT</td>\n</tr>\n</tbody></table>\n<p>O <code>issuer</code> é o valor de <code>PUBLIC_API_URL</code>. Se essa variável estiver errada, a descoberta aponta para o lugar errado. Veja <code>configuration.md</code>.</p>\n<h4 id=\"mcp-visao-geral-passo-a-passo\" style=\"margin-top:20px\">Passo a passo</h4>\n<p class=\"muted\">Diagrama disponível na documentação do repositório (docs/mcp/overview.md).</p>\n<p>Regras que o servidor aplica em cada etapa:</p>\n<ol>\n<li><strong>401 com <code>WWW-Authenticate</code>.</strong> Toda resposta 401 em <code>/mcp</code> traz <code>Bearer resource_metadata=&quot;&lt;issuer&gt;/.well-known/oauth-protected-resource/mcp&quot;</code>. Sem isso o cliente teria de adivinhar a URL dos metadados e nunca completaria a reautenticação sozinho.</li>\n<li><strong>Registro (<code>/register</code>).</strong> Exige <code>redirect_uris</code> (lista). Cada URI deve ser <code>https://</code>, ou <code>http://localhost</code> / <code>http://127.0.0.1</code> (RFC 8252, clientes nativos com loopback). Outros esquemas (<code>javascript:</code>, <code>data:</code>, <code>file:</code>) são rejeitados. O cliente fica guardado no Redis por <strong>180 dias</strong>; se o Redis for esvaziado, o cliente simplesmente se registra de novo.</li>\n<li><strong>Autorização (<code>GET /authorize</code>).</strong> Exige <code>client_id</code>, <code>redirect_uri</code>, <code>code_challenge</code> (43 a 128 caracteres) e <code>code_challenge_method=S256</code>. <code>plain</code> é rejeitado. O <code>client_id</code> precisa existir e o <code>redirect_uri</code> precisa ser um dos registrados. Parâmetros inválidos retornam 400 sem redirecionar (evita open redirect). Os parâmetros ficam guardados no Redis sob uma chave opaca (válida por <strong>30 minutos</strong>), e o formulário só carrega essa chave, não os valores crus.</li>\n<li><strong>Login (<code>POST /authorize</code>).</strong> Usa a mesma validação de e-mail e senha do painel, com proteção contra força bruta em três camadas (IP + conta, IP, cookie de dispositivo). Passando, emite um <strong>código de autorização de uso único, válido por 90 segundos</strong>, e redireciona para o <code>redirect_uri</code> com <code>code</code> e <code>state</code>.</li>\n<li><strong>Token (<code>POST /token</code>).</strong> Aceita JSON ou formulário (<code>application/x-www-form-urlencoded</code>). Exige <code>grant_type=authorization_code</code>, <code>code</code>, <code>code_verifier</code> (43 a 128 caracteres), <code>client_id</code> e <code>redirect_uri</code>. O código é apagado ao ser lido, mesmo que o PKCE falhe depois (não há replay). Qualquer motivo de rejeição devolve o mesmo <code>400 invalid_grant</code>, sem revelar qual validação falhou.</li>\n</ol>\n<h3 id=\"mcp-visao-geral-token-sessão-e-expiração\" style=\"margin-top:20px\">Token, sessão e expiração</h3>\n<p>O <code>access_token</code> é um <strong>JWT idêntico ao do login do painel</strong>, com <code>userId</code>, <code>apiClientId</code>, <code>accountRole</code> e <code>jti</code>. Duas coisas definem a vida da sessão:</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Mecanismo</th>\n<th>Variável</th>\n<th>Padrão</th>\n<th>Efeito</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Validade absoluta do JWT</td>\n<td><code>JWT_EXPIRES_IN</code></td>\n<td><code>7d</code></td>\n<td>É o valor anunciado em <code>expires_in</code> (calculado como <code>exp - iat</code> do próprio JWT)</td>\n</tr>\n<tr>\n<td>Inatividade (deslizante, no Redis)</td>\n<td><code>SESSION_IDLE_TIMEOUT_MIN</code></td>\n<td><code>30</code></td>\n<td>Cada requisição autenticada renova o prazo; sem uso, a sessão morre antes do JWT expirar</td>\n</tr>\n</tbody></table>\n<p>Consequências práticas:</p>\n<ul>\n<li>Com uso contínuo, o cliente não precisa logar de novo até o JWT vencer.</li>\n<li>Depois de mais de <code>SESSION_IDLE_TIMEOUT_MIN</code> minutos sem nenhuma requisição, a próxima chamada recebe <code>401 Sessão expirada. Faça login novamente.</code>, com o <code>WWW-Authenticate</code> descrito acima. O cliente deve refazer o login.</li>\n<li><strong>Não há <code>refresh_token</code> nesta versão.</strong> Ao fim da sessão, o usuário refaz o login no navegador.</li>\n<li>O <code>expires_in</code> anunciado precisa refletir a vida real do JWT, não o tempo de inatividade. Anunciar o tempo de inatividade (30 min) faz clientes que tratam <code>expires_in</code> como validade fixa derrubarem a sessão mesmo com uso contínuo. Veja <a href=\"#mcp-problemas\">Solução de problemas</a>.</li>\n<li>Logout ou exclusão do usuário invalidam a sessão na hora, mesmo com o JWT ainda dentro da validade.</li>\n</ul>\n<h3 id=\"mcp-visao-geral-multi-tenant-e-papéis\" style=\"margin-top:20px\">Multi-tenant e papéis</h3>\n<p>Toda tool roda com a identidade do usuário que fez login. O servidor nunca decide escopo na camada MCP; quem decide é a rota REST injetada.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Papel</th>\n<th>O que as tools alcançam</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>MEMBER</strong></td>\n<td>Apenas as instâncias das quais é dono (<code>ownerUserId</code>) e as mensagens delas. Instância de outro MEMBER responde <code>404</code></td>\n</tr>\n<tr>\n<td><strong>OWNER</strong></td>\n<td>Todas as instâncias da conta e as tools de membros (<code>apienvios_*_member</code>)</td>\n</tr>\n<tr>\n<td><strong>SUPER_ADMIN</strong></td>\n<td>Alcance igual ou maior que o de OWNER, conforme a tabela de papéis do README. As rotas de administração global (<code>/v1/admin/*</code>) não são tools</td>\n</tr>\n</tbody></table>\n<p>Se quem fez login não for OWNER nem SUPER_ADMIN, as tools de membros respondem <code>403</code>.</p>\n<p>Fora do escopo desta versão (não existem como tool): administração global (<code>/v1/admin/*</code>), rotas por token de instância (envio máquina a máquina) e ações raras por instância (presença, reação, leitura, verificação de número).</p>\n<h3 id=\"mcp-visao-geral-limites-e-anti-flood\" style=\"margin-top:20px\">Limites e anti-flood</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Limite</th>\n<th>Valor padrão</th>\n<th>Onde configurar</th>\n<th>Resposta</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Rate limit global por requisição</td>\n<td><code>DEFAULT_RATE_LIMIT</code> = 100 por minuto</td>\n<td><code>.env</code></td>\n<td><code>429 Rate limit excedido para este cliente</code></td>\n</tr>\n<tr>\n<td>Envios ao mesmo destinatário, por conta</td>\n<td>10 por hora (<code>maxPerRecipientPerHour</code> da conta)</td>\n<td>Campo da conta</td>\n<td><code>429</code> com <code>Retry-After</code></td>\n</tr>\n<tr>\n<td>Mensagens por número, por dia</td>\n<td><code>MAX_MESSAGES_PER_NUMBER_DAY</code> = 200</td>\n<td><code>.env</code></td>\n<td>Aplicado pela fila de envio</td>\n</tr>\n<tr>\n<td>Instâncias por conta</td>\n<td><code>maxInstances</code> da conta (padrão 1)</td>\n<td>Campo da conta</td>\n<td>Erro ao criar a instância</td>\n</tr>\n<tr>\n<td>Tentativas de login no <code>/authorize</code></td>\n<td>5 por 15 min por IP + conta; 20 por 15 min por IP; 20 por 15 min por dispositivo</td>\n<td><code>LOGIN_MAX_*</code> e <code>LOGIN_JANELA_*</code></td>\n<td>Página de login com erro de bloqueio</td>\n</tr>\n</tbody></table>\n<p>Observação sobre o rate limit global: para chamadas autenticadas por JWT (painel e MCP) o balde é o <strong>IP do cliente</strong>. O servidor repassa o IP da requisição <code>/mcp</code> original para a chamada interna, para não juntar todos os usuários no mesmo balde. O IP só é confiável quando o proxy reverso fica numa faixa privada (<code>trustProxy</code> aceita <code>loopback</code> e <code>uniquelocal</code>); veja <code>self-hosting.md</code>.</p>\n<p>O <code>/mcp/oauth/authorize</code> fica fora do rate limit global de propósito, porque já tem proteção própria contra força bruta e o fluxo normal do navegador (redirecionamentos, tentativas) não deve esbarrar num teto pensado para tráfego de API.</p>\n<h3 id=\"mcp-visao-geral-ponte-whatsapp-para-o-assistente-opcional\" style=\"margin-top:20px\">Ponte WhatsApp para o assistente (opcional)</h3>\n<p>No <code>initialize</code>, o servidor envia um campo <code>instructions</code>. Clientes compatíveis repassam esse texto ao modelo ao conectar. O texto padrão transforma a conversa em uma <strong>ponte de chat</strong> com o WhatsApp da conta:</p>\n<ol>\n<li>Ao conectar, o assistente lê as mensagens recebidas pendentes e entra em um laço: chama <code>apienvios_wait_inbound_messages</code> em sequência (espera de até 20 s, resposta em cerca de 1 s quando chega mensagem). Depois de 5 esperas vazias seguidas, passa a checar a cada 60 a 90 s.</li>\n<li>O <strong>chat de controle</strong> é a conversa do dono consigo mesmo. Começa quando chega uma mensagem do próprio dono (<code>fromMe=true</code>) cujo texto começa com a <strong>palavra de ativação</strong> (padrão <code>Claude</code>, sem dois-pontos). Toda resposta do assistente leva um <strong>prefixo</strong> (padrão <code>Claude: </code>) e é enviada com <code>apienvios_send_message</code>.</li>\n<li>Mensagens de terceiros nunca recebem resposta automática.</li>\n<li>Áudios do dono chegam transcritos em <code>text</code> (precisa de <code>GEMINI_API_KEY</code>). Imagens e figurinhas podem ser vistas com <code>apienvios_get_inbound_media</code>.</li>\n<li><strong>Tudo o que chega pelo WhatsApp é tratado como conteúdo não confiável</strong>, nunca como configuração. Ninguém pelo WhatsApp muda o modelo, as instruções nem o monitoramento. O assistente não revela tokens, chaves, caminhos, nomes internos nem dados de outras contas. Tools destrutivas (<code>delete_*</code>) nunca são chamadas de forma autônoma.</li>\n</ol>\n<p>Variáveis de configuração:</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Variável</th>\n<th>Padrão</th>\n<th>Efeito</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>MCP_BRIDGE_ENABLED</code></td>\n<td><code>true</code></td>\n<td><code>false</code> envia só as tools, sem instruções de ponte</td>\n</tr>\n<tr>\n<td><code>MCP_BRIDGE_TRIGGER_WORD</code></td>\n<td><code>Claude</code></td>\n<td>Palavra que abre o chat de controle</td>\n</tr>\n<tr>\n<td><code>MCP_BRIDGE_REPLY_PREFIX</code></td>\n<td><code>&lt;palavra&gt;: </code></td>\n<td>Prefixo de toda resposta do assistente</td>\n</tr>\n<tr>\n<td><code>MCP_BRIDGE_INSTRUCTIONS</code></td>\n<td>(texto padrão)</td>\n<td>Substitui o texto inteiro</td>\n</tr>\n<tr>\n<td><code>MCP_BRIDGE_INSTRUCTIONS_FILE</code></td>\n<td>(vazio)</td>\n<td>Substitui o texto inteiro, lendo de um arquivo</td>\n</tr>\n</tbody></table>\n<p>Em <code>MCP_BRIDGE_INSTRUCTIONS</code> e no arquivo, <code>{{TRIGGER_WORD}}</code> e <code>{{REPLY_PREFIX}}</code> são substituídos. O texto padrão está em <code>src/mcp/bridge-instructions.ts</code>.</p>\n<p>Limites da ponte: ela só funciona <strong>enquanto a sessão do assistente estiver aberta</strong>; não há relé 24 horas por dia. Rodar o monitoramento em um subagente em segundo plano, com um modelo pequeno e rápido, libera a conversa principal, mas subagentes pequenos podem encerrar o laço sozinhos depois de um tempo e precisam ser retomados.</p>\n<h3 id=\"mcp-visao-geral-mais-informações\" style=\"margin-top:20px\">Mais informações</h3>\n<ul>\n<li><a href=\"#mcp-conectar\">Conectar um cliente</a>: como conectar cada cliente.</li>\n<li><a href=\"#mcp-ferramentas\">Ferramentas (30 tools)</a>: referência completa das tools.</li>\n<li><a href=\"#mcp-seguranca\">Segurança</a>: superfície de ataque, boas práticas e o que não expor.</li>\n<li><a href=\"#mcp-problemas\">Solução de problemas</a>: problemas conhecidos e soluções.</li>\n<li><a href=\"#mcp-exemplos\">Exemplos de uso</a>: exemplos de pedidos ao assistente.</li>\n</ul>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-conectar\" x-show=\"bate($el.textContent)\">\n<h2>Conectar um cliente de IA ao MCP</h2>\n<p>Este guia mostra como conectar o servidor MCP do Api-WhatsApp-MCP a cada cliente. Antes de começar, leia <a href=\"#mcp-visao-geral\">Visão geral</a> se quiser entender o fluxo de autenticação.</p>\n<p>Em todos os exemplos, troque <code>__MCP_API_BASE__/mcp</code> pela URL pública do seu servidor (o valor de <code>PUBLIC_API_URL</code> mais <code>/mcp</code>).</p>\n<h3 id=\"mcp-conectar-pré-requisitos\" style=\"margin-top:20px\">Pré-requisitos</h3>\n<ol>\n<li>O servidor precisa estar acessível por <strong>HTTPS</strong> na URL pública, com <code>PUBLIC_API_URL</code> apontando para ela e as rotas <code>/.well-known/oauth-*</code> e <code>/mcp*</code> encaminhadas ao app (veja <code>self-hosting.md</code>).</li>\n<li>Você precisa de um usuário no ApiEnvios (e-mail e senha). Para um assistente que só envia mensagens, prefira um usuário <strong>MEMBER</strong>, dono apenas das instâncias necessárias.</li>\n<li>O endpoint <code>/mcp</code> só aceita o <strong>JWT emitido pelo login OAuth</strong> (ou pelo login do painel). Uma chave de API de conta não funciona nele.</li>\n</ol>\n<h3 id=\"mcp-conectar-o-que-este-servidor-exige-do-cliente\" style=\"margin-top:20px\">O que este servidor exige do cliente</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Requisito</th>\n<th>Detalhe</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Transporte</td>\n<td>Streamable HTTP. Só <code>POST /mcp</code> (sem estado)</td>\n</tr>\n<tr>\n<td>Autenticação</td>\n<td>OAuth 2.1 com PKCE S256</td>\n</tr>\n<tr>\n<td>Registro do cliente</td>\n<td><strong>Dynamic Client Registration</strong> (<code>POST /mcp/oauth/register</code>). O servidor <strong>não</strong> suporta Client ID Metadata Documents nem registro prévio por painel</td>\n</tr>\n<tr>\n<td>Redirect</td>\n<td><code>https://...</code> ou <code>http://localhost</code> / <code>http://127.0.0.1</code></td>\n</tr>\n<tr>\n<td>Token</td>\n<td>Bearer, sem <code>refresh_token</code> (ao fim da sessão, novo login)</td>\n</tr>\n</tbody></table>\n<p>Clientes que não fazem Dynamic Client Registration precisam de um client_id registrado manualmente ou da ponte <code>mcp-remote</code>. Veja cada guia.</p>\n<h3 id=\"mcp-conectar-tabela-de-compatibilidade\" style=\"margin-top:20px\">Tabela de compatibilidade</h3>\n<p>Status de verificação: <strong>Verificado</strong> significa que a página oficial do cliente foi lida em <strong>2026-10-06</strong> e a configuração abaixo vem dela. <strong>Parcial</strong> significa que só parte foi confirmada. <strong>Não confirmado</strong> significa que a documentação oficial consultada não cobre o ponto, e o guia diz o que falta testar. Nenhum cliente da lista foi testado de ponta a ponta contra este repositório aberto nesta rodada de documentação; o mantenedor já usou Claude Code e o conector do claude.ai contra o sistema original.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Cliente</th>\n<th>HTTP remoto</th>\n<th>OAuth com DCR</th>\n<th>Status</th>\n<th>Guia</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Claude Code</td>\n<td>sim</td>\n<td>sim (fluxo <code>/mcp</code>)</td>\n<td>Verificado</td>\n<td><a href=\"#mcp-cliente-claude-code\">Guia: Claude Code</a></td>\n</tr>\n<tr>\n<td>claude.ai, Claude Desktop</td>\n<td>sim (conector personalizado)</td>\n<td>sim (opção de registro automático)</td>\n<td>Verificado (UI e requisitos)</td>\n<td><a href=\"#mcp-cliente-claude-ai-desktop\">Guia: claude.ai e Desktop</a></td>\n</tr>\n<tr>\n<td>OpenAI Codex (CLI e extensão)</td>\n<td>sim</td>\n<td>sim (<code>--oauth-client-registration dcr</code>)</td>\n<td>Verificado</td>\n<td><a href=\"#mcp-cliente-codex\">Guia: Codex (OpenAI)</a></td>\n</tr>\n<tr>\n<td>ChatGPT (modo desenvolvedor)</td>\n<td>sim (HTTPS público)</td>\n<td>indicado em fontes secundárias</td>\n<td>Parcial</td>\n<td><a href=\"#mcp-cliente-chatgpt\">Guia: ChatGPT</a></td>\n</tr>\n<tr>\n<td>Cursor</td>\n<td>sim</td>\n<td><strong>não</strong> (a doc diz que DCR não é suportado)</td>\n<td>Verificado, com contorno não testado</td>\n<td><a href=\"#mcp-cliente-cursor\">Guia: Cursor</a></td>\n</tr>\n<tr>\n<td>VS Code (GitHub Copilot)</td>\n<td>sim</td>\n<td>não detalhado na doc consultada</td>\n<td>Parcial</td>\n<td><a href=\"#mcp-cliente-vscode\">Guia: VS Code (Copilot)</a></td>\n</tr>\n<tr>\n<td>Windsurf (docs atuais: Devin Desktop)</td>\n<td>sim</td>\n<td>sim (a doc cita OAuth)</td>\n<td>Verificado</td>\n<td><a href=\"#mcp-cliente-windsurf\">Guia: Windsurf</a></td>\n</tr>\n<tr>\n<td>Gemini CLI</td>\n<td>sim (<code>httpUrl</code>)</td>\n<td>sim, exige navegador local</td>\n<td>Verificado</td>\n<td><a href=\"#mcp-cliente-gemini-cli\">Guia: Gemini CLI</a></td>\n</tr>\n<tr>\n<td>Cline</td>\n<td>sim (<code>streamableHttp</code>)</td>\n<td>a doc não menciona OAuth</td>\n<td>Parcial</td>\n<td><a href=\"#mcp-cliente-cline\">Guia: Cline</a></td>\n</tr>\n<tr>\n<td>Zed</td>\n<td>sim</td>\n<td>sim</td>\n<td>Verificado</td>\n<td><a href=\"#mcp-cliente-zed\">Guia: Zed</a></td>\n</tr>\n<tr>\n<td>Continue</td>\n<td>sim (<code>streamable-http</code>)</td>\n<td>a doc não menciona OAuth</td>\n<td>Parcial</td>\n<td><a href=\"#mcp-cliente-continue\">Guia: Continue</a></td>\n</tr>\n<tr>\n<td>Qualquer cliente só com stdio</td>\n<td>via <code>mcp-remote</code></td>\n<td>sim (navegador local)</td>\n<td>Verificado (README do projeto)</td>\n<td><a href=\"#mcp-cliente-mcp-remote\">Guia: mcp-remote</a></td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-conectar-escolha-rápida\" style=\"margin-top:20px\">Escolha rápida</h3>\n<ul>\n<li>Quer o caminho mais direto, na linha de comando: <a href=\"#mcp-cliente-claude-code\">Claude Code</a> ou <a href=\"#mcp-cliente-codex\">Codex</a>.</li>\n<li>Prefere interface gráfica: <a href=\"#mcp-cliente-claude-ai-desktop\">claude.ai e Claude Desktop</a>.</li>\n<li>Seu cliente não faz DCR ou só fala stdio: <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>.</li>\n<li>Servidor numa máquina remota sem navegador: veja a seção &quot;Máquina remota&quot; em cada guia e em <a href=\"#mcp-problemas\">Solução de problemas</a>.</li>\n</ul>\n<h3 id=\"mcp-conectar-depois-de-conectar\" style=\"margin-top:20px\">Depois de conectar</h3>\n<ol>\n<li>Confira as tools: peça ao assistente &quot;liste as instâncias&quot; (<code>apienvios_list_instances</code>).</li>\n<li>Se você também quer a ponte de WhatsApp (o assistente respondendo mensagens), veja a seção &quot;Ponte WhatsApp&quot; em <a href=\"#mcp-visao-geral\">Visão geral</a>.</li>\n<li>Exemplos de pedidos: <a href=\"#mcp-exemplos\">Exemplos de uso</a>.</li>\n<li>Se as tools não aparecerem logo depois do login, veja <a href=\"#mcp-problemas\">Solução de problemas</a>.</li>\n</ol>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-claude-code\" x-show=\"bate($el.textContent)\">\n<h2>Claude Code</h2>\n<p>Status: <strong>Verificado</strong> na documentação oficial em 2026-10-06 (<a href=\"https://code.claude.com/docs/en/mcp\" target=\"_blank\" rel=\"noopener noreferrer\">Claude Code: MCP</a>). Testado pelo mantenedor contra o sistema original.</p>\n<h3 id=\"mcp-cliente-claude-code-conectar\" style=\"margin-top:20px\">Conectar</h3>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>claude mcp add --transport http apienvios __MCP_API_BASE__/mcp</code></pre></div>\n<p>Depois, dentro do Claude Code:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>/mcp</code></pre></div>\n<p>Escolha <code>apienvios</code> e autentique no navegador (e-mail e senha do ApiEnvios). Enquanto não autenticar, o servidor aparece como &quot;Needs authentication&quot;.</p>\n<p>Por linha de comando, também é possível:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>claude mcp login apienvios            # abre o navegador\nclaude mcp login apienvios --no-browser   # imprime a URL de autorização\nclaude mcp logout apienvios           # apaga as credenciais</code></pre></div>\n<h3 id=\"mcp-cliente-claude-code-escopos-e-arquivos\" style=\"margin-top:20px\">Escopos e arquivos</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Escopo</th>\n<th>Onde fica</th>\n<th>Quando vale</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>local</code> (padrão)</td>\n<td><code>~/.claude.json</code></td>\n<td>Só no projeto atual</td>\n</tr>\n<tr>\n<td><code>project</code></td>\n<td><code>.mcp.json</code> na raiz do projeto</td>\n<td>Compartilhado com a equipe (versionado)</td>\n</tr>\n<tr>\n<td><code>user</code></td>\n<td><code>~/.claude.json</code></td>\n<td>Todos os seus projetos</td>\n</tr>\n</tbody></table>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>claude mcp add --transport http --scope user apienvios __MCP_API_BASE__/mcp</code></pre></div>\n<p>Formato do <code>.mcp.json</code> para um servidor HTTP:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;type&quot;: &quot;http&quot;,\n      &quot;url&quot;: &quot;__MCP_API_BASE__/mcp&quot;\n    }\n  }\n}</code></pre></div>\n<p>Não coloque tokens nem senhas nesse arquivo. A autenticação deste servidor é por OAuth e fica guardada pelo próprio Claude Code. Servidores de projeto pedem aprovação antes de conectar.</p>\n<p>Outros comandos úteis: <code>claude mcp list</code>, <code>claude mcp get apienvios</code>, <code>claude mcp remove apienvios</code> e <code>claude mcp add-json apienvios &#39;{&quot;type&quot;:&quot;http&quot;,&quot;url&quot;:&quot;__MCP_API_BASE__/mcp&quot;}&#39;</code>.</p>\n<h3 id=\"mcp-cliente-claude-code-máquina-remota-ssh-terminal-web\" style=\"margin-top:20px\">Máquina remota (SSH, terminal web)</h3>\n<p>Quando o Claude Code roda em outra máquina, o navegador do seu computador não consegue abrir <code>http://localhost:&lt;porta&gt;/callback</code>, e a página dá erro de conexão. Isso é esperado. A documentação oficial manda colar a <strong>URL completa da barra de endereço</strong> (<code>http://localhost:&lt;porta&gt;/callback?code=...&amp;state=...</code>) no campo de URL que o Claude Code mostra.</p>\n<p>Cuidados:</p>\n<ul>\n<li>Use a URL da <strong>tentativa mais recente</strong>. Cada novo login invalida o anterior.</li>\n<li>Cole logo, o código de autorização vale 90 segundos.</li>\n<li>Se aparecer &quot;No OAuth flow is in progress&quot;, comece o login de novo e cole a URL da última tentativa.</li>\n</ul>\n<h3 id=\"mcp-cliente-claude-code-porta-fixa-do-callback\" style=\"margin-top:20px\">Porta fixa do callback</h3>\n<p>Se você precisar de uma porta de callback fixa (por exemplo, para liberar no firewall):</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>claude mcp add --transport http --callback-port 8080 apienvios __MCP_API_BASE__/mcp</code></pre></div>\n<p>Este servidor aceita qualquer <code>http://localhost:&lt;porta&gt;/callback</code> no registro, então a porta fixa funciona. Você não precisa de <code>--client-id</code>: o cliente se registra sozinho por DCR.</p>\n<h3 id=\"mcp-cliente-claude-code-depois-do-login-as-tools-não-aparecem\" style=\"margin-top:20px\">Depois do login: as tools não aparecem</h3>\n<p>Algumas versões só carregam a lista de tools no início da sessão. Se o <code>/mcp</code> mostrar &quot;Authentication successful&quot; e as tools <code>apienvios_*</code> não aparecerem, saia e retome a sessão (<code>claude --continue</code>). Esta observação vem da prática do mantenedor, não da documentação oficial.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-claude-ai-desktop\" x-show=\"bate($el.textContent)\">\n<h2>claude.ai e Claude Desktop</h2>\n<p>Status: <strong>Verificado</strong> (interface, planos e requisitos de rede) no artigo oficial <a href=\"https://support.claude.com/en/articles/11175166-get-started-with-custom-connectors-using-remote-mcp\" target=\"_blank\" rel=\"noopener noreferrer\">Get started with custom connectors using remote MCP</a>, lido em 2026-10-06. O artigo não detalha o fluxo técnico (URL de callback, transporte); isso vem da prática.</p>\n<h3 id=\"mcp-cliente-claude-ai-desktop-conectar\" style=\"margin-top:20px\">Conectar</h3>\n<ol>\n<li>Abra <strong>Customize &gt; Connectors</strong> e escolha <strong>Add custom connector</strong>.</li>\n<li>Informe um nome e a URL do servidor: <code>__MCP_API_BASE__/mcp</code>.</li>\n<li>Em autenticação, o artigo descreve três opções: <strong>Use Claude&#39;s published identity (Recommended)</strong>, <strong>Register automatically</strong> e <strong>Use your own OAuth client</strong>. Este servidor registra clientes por <strong>Dynamic Client Registration</strong>, então a opção de <strong>registro automático</strong> é a que corresponde ao que ele oferece. Se a opção recomendada falhar, troque para o registro automático. Qual opção funciona exatamente com este servidor não foi validado nesta rodada.</li>\n<li>Faça login com e-mail e senha do ApiEnvios quando o navegador abrir.</li>\n</ol>\n<p>Conectores criados no claude.ai valem também no Claude Desktop, no Cowork e nos aplicativos móveis, porque a conexão sai da infraestrutura da Anthropic, não do seu computador. Os planos Free, Pro, Max, Team e Enterprise têm conectores personalizados, segundo o artigo (nomes e limites de plano mudam; confira o artigo).</p>\n<h3 id=\"mcp-cliente-claude-ai-desktop-requisito-de-rede\" style=\"margin-top:20px\">Requisito de rede</h3>\n<p>O artigo é explícito: o servidor MCP precisa ser acessível pela <strong>internet pública</strong>, a partir dos IPs da Anthropic. Um servidor em rede privada não conecta, mesmo que você consiga acessá-lo do seu computador. Isso vale para este servidor: ele precisa de HTTPS público (veja <code>self-hosting.md</code>).</p>\n<h3 id=\"mcp-cliente-claude-ai-desktop-observação-sobre-o-tempo-do-login\" style=\"margin-top:20px\">Observação sobre o tempo do login</h3>\n<p>O assistente de conexão do claude.ai tem várias etapas de verificação antes de mostrar o formulário de login, e depois você ainda digita e-mail e senha. Por isso este servidor guarda os parâmetros de autorização por <strong>30 minutos</strong> (e o código final por 90 segundos). Se aparecer &quot;Sessão de autorização expirada&quot;, recomece pela tela de conexão.</p>\n<h3 id=\"mcp-cliente-claude-ai-desktop-claude-desktop-sem-conector-arquivo-de-configuração\" style=\"margin-top:20px\">Claude Desktop sem conector (arquivo de configuração)</h3>\n<p>Para o Claude Desktop o caminho recomendado é o conector acima. Se o seu aplicativo só aceitar servidores locais por arquivo, use a ponte <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-codex\" x-show=\"bate($el.textContent)\">\n<h2>OpenAI Codex (CLI e extensão para IDE)</h2>\n<p>Status: <strong>Verificado</strong> na documentação oficial em 2026-10-06 (<a href=\"https://developers.openai.com/codex/mcp\" target=\"_blank\" rel=\"noopener noreferrer\">Codex: MCP</a>, que redireciona para <code>learn.chatgpt.com/docs/extend/mcp</code>). Formatos de configuração mudam com frequência: confirme a página oficial antes de automatizar.</p>\n<h3 id=\"mcp-cliente-codex-conectar-pela-linha-de-comando\" style=\"margin-top:20px\">Conectar pela linha de comando</h3>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>codex mcp add apienvios --url __MCP_API_BASE__/mcp\ncodex mcp login apienvios --oauth-client-registration dcr</code></pre></div>\n<p>O Codex escolhe sozinho entre dois modos de registro de cliente OAuth: Client ID Metadata Documents (CIMD), quando o servidor oferece, e Dynamic Client Registration (DCR). Este servidor oferece <strong>somente DCR</strong>, então use <code>--oauth-client-registration dcr</code> (ou deixe o Codex escolher; ele cai em DCR quando não há CIMD).</p>\n<p>Outros comandos: <code>codex mcp list</code>, <code>codex mcp logout apienvios</code>, <code>codex mcp remove apienvios</code>, <code>codex mcp --help</code>.</p>\n<h3 id=\"mcp-cliente-codex-conectar-pelo-arquivo-de-configuração\" style=\"margin-top:20px\">Conectar pelo arquivo de configuração</h3>\n<p>A configuração fica em <code>~/.codex/config.toml</code> (global) ou <code>.codex/config.toml</code> (por projeto, só em projetos confiáveis). O aplicativo do ChatGPT para desktop, a CLI e a extensão para IDE compartilham essa configuração.</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>[mcp_servers.apienvios]\nurl = &quot;__MCP_API_BASE__/mcp&quot;\nenabled = true\nstartup_timeout_sec = 20\ntool_timeout_sec = 60</code></pre></div>\n<p>Outras chaves documentadas para servidores HTTP: <code>bearer_token_env_var</code>, <code>http_headers</code>, <code>env_http_headers</code>, <code>enabled_tools</code> e <code>disabled_tools</code>. Esta última é útil para esconder tools destrutivas:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>disabled_tools = [&quot;apienvios_delete_instance&quot;, &quot;apienvios_delete_message&quot;, &quot;apienvios_delete_webhook&quot;, &quot;apienvios_delete_member&quot;]</code></pre></div>\n<p>Não use <code>bearer_token_env_var</code> com este servidor: o <code>/mcp</code> só aceita o JWT do login OAuth, que expira por inatividade.</p>\n<h3 id=\"mcp-cliente-codex-extensão-para-ide\" style=\"margin-top:20px\">Extensão para IDE</h3>\n<p>Na extensão: engrenagem, <strong>MCP servers</strong>, <strong>Add server</strong>, escolha o transporte <strong>Streamable HTTP</strong>, informe a URL e use <strong>Restart extension</strong>. Servidores que precisam de login mostram o botão <strong>Authenticate</strong>.</p>\n<h3 id=\"mcp-cliente-codex-callback-do-oauth\" style=\"margin-top:20px\">Callback do OAuth</h3>\n<p>A documentação lista <code>mcp_oauth_callback_port</code>, <code>mcp_oauth_callback_url</code> e o bloco <code>[mcp_servers.&lt;nome&gt;.oauth]</code> (<code>client_id</code>, <code>callback_url</code>, <code>callback_port</code>). A mesma página diz que callbacks estáveis exigem que o servidor de autorização informe <code>authorization_response_iss_parameter_supported: true</code>. <strong>Este servidor não anuncia esse campo</strong> (veja os metadados em <code>src/routes/mcp-metadata.route.ts</code>). Por isso, não configure <code>callback_url</code> estável; use o padrão do Codex (porta de loopback efêmera) ou apenas <code>callback_port</code> se precisar liberar uma porta. Esta conclusão combina a documentação do Codex com os metadados deste servidor e não foi testada.</p>\n<h3 id=\"mcp-cliente-codex-máquina-remota-ou-sem-navegador\" style=\"margin-top:20px\">Máquina remota ou sem navegador</h3>\n<p>A página consultada não descreve o fluxo para máquina sem navegador. <strong>Não confirmado.</strong> Consulte <code>codex mcp login --help</code> e a documentação do Codex antes de depender disso em servidores remotos.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-cursor\" x-show=\"bate($el.textContent)\">\n<h2>Cursor</h2>\n<p>Status: <strong>Verificado</strong> na documentação oficial em 2026-10-06 (<a href=\"https://cursor.com/docs/context/mcp\" target=\"_blank\" rel=\"noopener noreferrer\">Cursor: MCP</a>). O contorno descrito para a falta de DCR <strong>não foi testado</strong>.</p>\n<h3 id=\"mcp-cliente-cursor-o-ponto-crítico\" style=\"margin-top:20px\">O ponto crítico</h3>\n<p>A documentação oficial diz que o Cursor aceita servidores remotos por <strong>SSE e Streamable HTTP</strong>, com OAuth, mas que <strong>Dynamic Client Registration não é suportado</strong>: é preciso informar um <code>CLIENT_ID</code> estático no bloco <code>auth</code>. Este servidor só registra clientes por DCR, então a configuração simples (somente <code>url</code>) pode não completar o login.</p>\n<h3 id=\"mcp-cliente-cursor-configuração-básica\" style=\"margin-top:20px\">Configuração básica</h3>\n<p>Arquivo <code>.cursor/mcp.json</code> (projeto) ou <code>~/.cursor/mcp.json</code> (global):</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;url&quot;: &quot;__MCP_API_BASE__/mcp&quot;\n    }\n  }\n}</code></pre></div>\n<h3 id=\"mcp-cliente-cursor-contorno-registrar-o-cliente-à-mão\" style=\"margin-top:20px\">Contorno: registrar o cliente à mão</h3>\n<p>A documentação do Cursor informa o redirect estático do desktop: <code>http://localhost:8787/callback</code>. Este servidor aceita registrar um cliente com esse redirect. Registre uma vez:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>curl -sS -X POST __MCP_API_BASE__/mcp/oauth/register \\\n  -H &#39;Content-Type: application/json&#39; \\\n  -d &#39;{&quot;client_name&quot;:&quot;Cursor&quot;,&quot;redirect_uris&quot;:[&quot;http://localhost:8787/callback&quot;]}&#39;</code></pre></div>\n<p>A resposta traz o <code>client_id</code>. Use-o no bloco <code>auth</code> da configuração:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;url&quot;: &quot;__MCP_API_BASE__/mcp&quot;,\n      &quot;auth&quot;: {\n        &quot;CLIENT_ID&quot;: &quot;&lt;client_id da resposta&gt;&quot;\n      }\n    }\n  }\n}</code></pre></div>\n<p>Pontos não confirmados: a documentação do Cursor mostra <code>CLIENT_SECRET</code> ao lado de <code>CLIENT_ID</code>, e não diz se ele é opcional para clientes públicos. O cliente deste servidor é público e <strong>não tem segredo</strong>. Se o Cursor exigir o campo, esse contorno não funciona e a saída é a ponte <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>.</p>\n<p>O cliente registrado fica guardado por 180 dias; depois disso, registre de novo.</p>\n<h3 id=\"mcp-cliente-cursor-alternativa-mcp-remote\" style=\"margin-top:20px\">Alternativa: mcp-remote</h3>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;command&quot;: &quot;npx&quot;,\n      &quot;args&quot;: [&quot;-y&quot;, &quot;mcp-remote&quot;, &quot;__MCP_API_BASE__/mcp&quot;]\n    }\n  }\n}</code></pre></div>\n<p>Detalhes em <a href=\"#mcp-cliente-mcp-remote\">Guia: mcp-remote</a>.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-vscode\" x-show=\"bate($el.textContent)\">\n<h2>VS Code (GitHub Copilot)</h2>\n<p>Status: <strong>Parcial</strong>. Formato de arquivo e comandos <strong>verificados</strong> na documentação oficial em 2026-10-06 (<a href=\"https://code.visualstudio.com/docs/copilot/customization/mcp-servers\" target=\"_blank\" rel=\"noopener noreferrer\">VS Code: MCP servers</a>). O suporte a OAuth e a Dynamic Client Registration <strong>não</strong> aparecem no conteúdo consultado.</p>\n<h3 id=\"mcp-cliente-vscode-configuração\" style=\"margin-top:20px\">Configuração</h3>\n<p>Arquivo <code>.vscode/mcp.json</code> no workspace (ou o arquivo do perfil de usuário, aberto pelo comando <strong>MCP: Open User Configuration</strong>). Atenção: o VS Code usa a chave <code>&quot;servers&quot;</code>, não <code>&quot;mcpServers&quot;</code>.</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;servers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;type&quot;: &quot;http&quot;,\n      &quot;url&quot;: &quot;__MCP_API_BASE__/mcp&quot;\n    }\n  }\n}</code></pre></div>\n<p>Formatos portáteis (<code>.mcp.json</code> na raiz do workspace ou <code>~/.copilot/mcp-config.json</code>) usam <code>&quot;mcpServers&quot;</code>.</p>\n<h3 id=\"mcp-cliente-vscode-comandos\" style=\"margin-top:20px\">Comandos</h3>\n<ul>\n<li><strong>MCP: Add Server</strong>: fluxo guiado.</li>\n<li><strong>MCP: List Servers</strong>: lista, inicia, para e reautentica servidores.</li>\n<li><strong>MCP: Open User Configuration</strong>: abre a configuração do perfil.</li>\n</ul>\n<h3 id=\"mcp-cliente-vscode-autenticação\" style=\"margin-top:20px\">Autenticação</h3>\n<p>A documentação consultada recomenda não gravar segredos no arquivo e usar variáveis de entrada (<code>inputs</code>). Este servidor usa OAuth: sem cabeçalho de autorização configurado, o esperado é que o VS Code abra o fluxo de login ao conectar. <strong>Isso não foi confirmado.</strong> Teste: adicione o servidor, inicie-o pela lista de servidores e veja se o navegador abre <code>.../mcp/oauth/authorize</code>. Se não abrir, use <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-windsurf\" x-show=\"bate($el.textContent)\">\n<h2>Windsurf (Cascade)</h2>\n<p>Status: <strong>Verificado</strong> na documentação oficial em 2026-10-06. A página antiga (<code>docs.windsurf.com/windsurf/cascade/mcp</code>) redireciona para a documentação atual em <code>docs.devin.ai/desktop/cascade/mcp</code>, onde o produto aparece como <strong>Devin Desktop</strong>. Nomes e caminhos mudaram; confirme na página oficial.</p>\n<h3 id=\"mcp-cliente-windsurf-configuração\" style=\"margin-top:20px\">Configuração</h3>\n<p>Segundo a documentação atual, o arquivo é <code>~/.config/devin/mcp_config.json</code> no macOS e Linux (ou <code>$XDG_CONFIG_HOME/devin/mcp_config.json</code>) e <code>%APPDATA%\\devin\\mcp_config.json</code> no Windows. O caminho <code>~/.codeium/windsurf/mcp_config.json</code>, muito citado em guias antigos, <strong>não aparece</strong> na documentação atual. Para abrir o arquivo certo, use o painel do Cascade: menu de ações (<code>...</code>) no topo do painel, seção MCPs, <strong>Open MCP config file</strong>.</p>\n<p>Para servidores HTTP a chave da URL é <code>serverUrl</code>:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;serverUrl&quot;: &quot;__MCP_API_BASE__/mcp&quot;\n    }\n  }\n}</code></pre></div>\n<p>A documentação diz que há suporte a três transportes (<code>stdio</code>, <code>Streamable HTTP</code> e <code>SSE</code>) e que o OAuth é suportado em cada um. Interpolação de variáveis: <code>${env:NOME}</code> e <code>${file:/caminho}</code>.</p>\n<h3 id=\"mcp-cliente-windsurf-pontos-não-confirmados\" style=\"margin-top:20px\">Pontos não confirmados</h3>\n<ul>\n<li>Se o registro do cliente por Dynamic Client Registration funciona com este servidor. Se o login não abrir ou falhar, use <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>.</li>\n</ul>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-gemini-cli\" x-show=\"bate($el.textContent)\">\n<h2>Gemini CLI</h2>\n<p>Status: <strong>Verificado</strong> na documentação oficial em 2026-10-06 (<a href=\"https://geminicli.com/docs/tools/mcp-server/\" target=\"_blank\" rel=\"noopener noreferrer\">Gemini CLI: MCP servers</a>).</p>\n<h3 id=\"mcp-cliente-gemini-cli-conectar-pela-linha-de-comando\" style=\"margin-top:20px\">Conectar pela linha de comando</h3>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>gemini mcp add --transport http apienvios __MCP_API_BASE__/mcp</code></pre></div>\n<p>Dentro do Gemini CLI, <code>/mcp</code> mostra os servidores, as tools e o estado da conexão, e <code>/mcp auth apienvios</code> conduz a autenticação OAuth.</p>\n<h3 id=\"mcp-cliente-gemini-cli-conectar-pelo-arquivo\" style=\"margin-top:20px\">Conectar pelo arquivo</h3>\n<p><code>~/.gemini/settings.json</code> (usuário) ou <code>.gemini/settings.json</code> (projeto). Para Streamable HTTP a chave é <code>httpUrl</code> (a chave <code>url</code> é para SSE):</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;httpUrl&quot;: &quot;__MCP_API_BASE__/mcp&quot;,\n      &quot;timeout&quot;: 30000\n    }\n  }\n}</code></pre></div>\n<h3 id=\"mcp-cliente-gemini-cli-oauth\" style=\"margin-top:20px\">OAuth</h3>\n<p>A documentação diz que o Gemini CLI detecta a exigência de OAuth pela resposta 401 e faz o registro dinâmico quando o servidor suporta, o que combina com este servidor (401 com <code>WWW-Authenticate</code>, metadados <code>.well-known</code> e <code>POST /mcp/oauth/register</code>).</p>\n<p>Limitação oficial: a autenticação exige que a <strong>máquina local consiga abrir um navegador</strong>. Ambientes sem navegador (SSH, contêiner) não completam o fluxo. Para esses casos não há contorno documentado; use outro cliente (por exemplo, <a href=\"#mcp-cliente-claude-code\">Claude Code</a>, que aceita colar a URL do callback).</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-cline\" x-show=\"bate($el.textContent)\">\n<h2>Cline</h2>\n<p>Status: <strong>Parcial</strong>. Formato de configuração <strong>verificado</strong> em 2026-10-06 (<a href=\"https://docs.cline.bot/mcp/configuring-mcp-servers\" target=\"_blank\" rel=\"noopener noreferrer\">Cline: configuring MCP servers</a>). A página <strong>não menciona OAuth</strong>, só cabeçalhos (<code>headers</code>).</p>\n<h3 id=\"mcp-cliente-cline-configuração\" style=\"margin-top:20px\">Configuração</h3>\n<p>Arquivo <code>cline_mcp_settings.json</code>, em <code>~/.cline/data/settings/</code> (o caminho pode ser alterado pela variável <code>CLINE_MCP_SETTINGS_PATH</code>). Na extensão para IDE: ícone <strong>MCP Servers</strong>, aba <strong>Configure</strong>, botão <strong>Configure MCP Servers</strong>. Há também a aba <strong>Remote Servers</strong>, em que você informa nome, URL e o tipo de transporte.</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;type&quot;: &quot;streamableHttp&quot;,\n      &quot;url&quot;: &quot;__MCP_API_BASE__/mcp&quot;,\n      &quot;disabled&quot;: false,\n      &quot;autoApprove&quot;: []\n    }\n  }\n}</code></pre></div>\n<p>Use <code>&quot;type&quot;: &quot;streamableHttp&quot;</code>: sem o campo, a documentação diz que o padrão é o transporte legado SSE, que este servidor não oferece.</p>\n<h3 id=\"mcp-cliente-cline-autenticação\" style=\"margin-top:20px\">Autenticação</h3>\n<p>Como a documentação não cita OAuth, <strong>não está confirmado</strong> que o Cline consiga fazer o login OAuth deste servidor. Duas saídas:</p>\n<ol>\n<li>Use a ponte <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>, que faz o OAuth no navegador e entrega ao Cline um servidor local por stdio.</li>\n<li>Cabeçalho <code>Authorization: Bearer &lt;JWT&gt;</code> com um JWT obtido pelo login da API. É frágil: a sessão expira por inatividade (padrão 30 minutos) e o JWT não é renovado. Use só para testes.</li>\n</ol>\n<p>Não deixe <code>autoApprove</code> liberar tools destrutivas (<code>apienvios_delete_*</code>).</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-zed\" x-show=\"bate($el.textContent)\">\n<h2>Zed</h2>\n<p>Status: <strong>Verificado</strong> na documentação oficial em 2026-10-06 (<a href=\"https://zed.dev/docs/ai/mcp\" target=\"_blank\" rel=\"noopener noreferrer\">Zed: MCP</a>).</p>\n<h3 id=\"mcp-cliente-zed-conectar\" style=\"margin-top:20px\">Conectar</h3>\n<p>Pela interface: <strong>Settings &gt; AI &gt; MCP Servers</strong>, <strong>Add Server</strong>, <strong>Add Remote Server</strong>. Ou pelo <code>settings.json</code>, na chave <code>context_servers</code>:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;context_servers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;url&quot;: &quot;__MCP_API_BASE__/mcp&quot;\n    }\n  }\n}</code></pre></div>\n<h3 id=\"mcp-cliente-zed-autenticação\" style=\"margin-top:20px\">Autenticação</h3>\n<p>A documentação diz que, quando um servidor remoto <strong>não tem</strong> cabeçalho <code>Authorization</code> configurado, o Zed pede que você se autentique pelo fluxo OAuth padrão do MCP. Portanto, <strong>não</strong> configure <code>headers</code> para este servidor: deixe só a <code>url</code> e faça o login quando o Zed pedir.</p>\n<p>Pontos não confirmados: o registro do cliente por Dynamic Client Registration com este servidor. Se falhar, use <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-continue\" x-show=\"bate($el.textContent)\">\n<h2>Continue</h2>\n<p>Status: <strong>Parcial</strong>. Formato <strong>verificado</strong> em 2026-10-06 (<a href=\"https://docs.continue.dev/customize/deep-dives/mcp\" target=\"_blank\" rel=\"noopener noreferrer\">Continue: MCP</a>); a página não cita cabeçalhos nem OAuth.</p>\n<h3 id=\"mcp-cliente-continue-configuração\" style=\"margin-top:20px\">Configuração</h3>\n<p>Um arquivo YAML em <code>.continue/mcpServers/</code> (por exemplo <code>.continue/mcpServers/apienvios.yaml</code>) ou dentro do <code>config.yaml</code>:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>mcpServers:\n  - name: apienvios\n    type: streamable-http\n    url: __MCP_API_BASE__/mcp</code></pre></div>\n<h3 id=\"mcp-cliente-continue-autenticação\" style=\"margin-top:20px\">Autenticação</h3>\n<p>A documentação consultada não menciona OAuth, então <strong>não está confirmado</strong> que o Continue consiga o login OAuth deste servidor. A saída é a ponte <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>, declarada como servidor local. Exemplo <strong>não verificado</strong> na documentação do Continue:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>mcpServers:\n  - name: apienvios\n    type: stdio\n    command: npx\n    args:\n      - &quot;-y&quot;\n      - mcp-remote\n      - __MCP_API_BASE__/mcp</code></pre></div>\n<p>Confira o formato do bloco <code>stdio</code> no manual do Continue antes de usar.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-chatgpt\" x-show=\"bate($el.textContent)\">\n<h2>ChatGPT (modo desenvolvedor)</h2>\n<p>Status: <strong>Parcial</strong>. A página oficial do artigo de ajuda (<a href=\"https://help.openai.com/en/articles/12584461-developer-mode-and-mcp-apps-in-chatgpt\" target=\"_blank\" rel=\"noopener noreferrer\">Developer mode and MCP apps in ChatGPT</a>) apareceu nos resultados de busca, mas a leitura direta foi bloqueada (HTTP 403) em 2026-10-06. O que está abaixo vem do resumo da busca da página oficial e de guias de terceiros, e <strong>não foi validado contra este servidor</strong>.</p>\n<h3 id=\"mcp-cliente-chatgpt-o-que-se-sabe\" style=\"margin-top:20px\">O que se sabe</h3>\n<ul>\n<li>Conectores MCP personalizados dependem do <strong>modo desenvolvedor</strong>, que é um recurso em beta e <strong>varia por plano</strong> (o resumo oficial cita planos Business e Enterprise/Edu para MCP completo, com leitura apenas em alguns planos). Confira no artigo oficial qual é o seu caso.</li>\n<li>O servidor precisa estar em uma <strong>URL HTTPS pública</strong>.</li>\n<li>Quando as tools escrevem ou alteram dados, a OpenAI espera OAuth 2.1 conforme a especificação de autorização do MCP, com PKCE e servidor de autorização descobrível. Este servidor segue esse desenho.</li>\n<li>O artigo oficial alerta para riscos de injeção de prompt ao conectar servidores: conecte apenas servidores em que você confia, e use um usuário MEMBER com poucas instâncias.</li>\n</ul>\n<h3 id=\"mcp-cliente-chatgpt-como-tentar\" style=\"margin-top:20px\">Como tentar</h3>\n<ol>\n<li>Ative o modo desenvolvedor conforme o artigo oficial (o caminho exato na interface muda; confirme no artigo).</li>\n<li>Crie um conector/app personalizado informando a URL <code>__MCP_API_BASE__/mcp</code> e escolha autenticação <strong>OAuth</strong>.</li>\n<li>Faça login com e-mail e senha do ApiEnvios.</li>\n</ol>\n<h3 id=\"mcp-cliente-chatgpt-o-que-não-foi-confirmado\" style=\"margin-top:20px\">O que não foi confirmado</h3>\n<ul>\n<li>Se o ChatGPT consegue registrar o cliente por Dynamic Client Registration neste servidor, ou se exige outra forma de registro.</li>\n<li>Quais tools de escrita ficam disponíveis em cada plano.</li>\n</ul>\n<p>Se o fluxo de OAuth do ChatGPT não funcionar, a alternativa é usar um cliente que funcione (por exemplo, <a href=\"#mcp-cliente-claude-code\">Claude Code</a> ou <a href=\"#mcp-cliente-codex\">Codex</a>). Se você validar o ChatGPT, contribua com a correção deste guia (veja <code>CONTRIBUTING.md</code>).</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-cliente-mcp-remote\" x-show=\"bate($el.textContent)\">\n<h2>Ponte mcp-remote (clientes só com stdio ou sem DCR)</h2>\n<p>Status: <strong>Verificado</strong> no README do projeto (<a href=\"https://github.com/geelen/mcp-remote\" target=\"_blank\" rel=\"noopener noreferrer\">geelen/mcp-remote</a>), lido em 2026-10-06. Ferramenta de terceiros: avalie antes de usar.</p>\n<p>O <code>mcp-remote</code> é um programa local (stdio) que conversa com um servidor MCP remoto e cuida do OAuth. Serve para clientes que só suportam servidores locais ou que não conseguem registrar o cliente OAuth sozinhos.</p>\n<h3 id=\"mcp-cliente-mcp-remote-configuração\" style=\"margin-top:20px\">Configuração</h3>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;mcpServers&quot;: {\n    &quot;apienvios&quot;: {\n      &quot;command&quot;: &quot;npx&quot;,\n      &quot;args&quot;: [&quot;-y&quot;, &quot;mcp-remote&quot;, &quot;__MCP_API_BASE__/mcp&quot;]\n    }\n  }\n}</code></pre></div>\n<p>Na primeira execução ele abre o navegador para o login e guarda as credenciais em <code>~/.mcp-auth</code>. Para limpar o estado e refazer o login: <code>rm -rf ~/.mcp-auth</code>.</p>\n<h3 id=\"mcp-cliente-mcp-remote-opções-úteis-segundo-o-readme\" style=\"margin-top:20px\">Opções úteis (segundo o README)</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Opção</th>\n<th>Efeito</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--transport http-only</code></td>\n<td>Força Streamable HTTP (o padrão é <code>http-first</code>). Este servidor só oferece HTTP</td>\n</tr>\n<tr>\n<td><code>--header &quot;Nome: valor&quot;</code></td>\n<td>Adiciona cabeçalho. Não use para guardar o JWT deste servidor (expira por inatividade)</td>\n</tr>\n<tr>\n<td><code>--host</code></td>\n<td>Muda o host do callback do OAuth (padrão <code>localhost</code>)</td>\n</tr>\n<tr>\n<td>número da porta, depois da URL</td>\n<td>Fixa a porta do callback</td>\n</tr>\n<tr>\n<td><code>--static-oauth-client-info</code></td>\n<td>Informa um cliente OAuth pré-registrado (JSON ou <code>@arquivo</code>)</td>\n</tr>\n</tbody></table>\n<p>Exemplo com porta fixa e transporte HTTP:</p>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code>{\n  &quot;args&quot;: [&quot;-y&quot;, &quot;mcp-remote&quot;, &quot;__MCP_API_BASE__/mcp&quot;, &quot;9696&quot;, &quot;--transport&quot;, &quot;http-only&quot;]\n}</code></pre></div>\n<h3 id=\"mcp-cliente-mcp-remote-máquina-sem-navegador\" style=\"margin-top:20px\">Máquina sem navegador</h3>\n<p>O README cita <code>--device-code</code> (fluxo de código no dispositivo) e <code>--client-credentials</code>. <strong>Nenhum dos dois funciona com este servidor</strong>: os metadados anunciam somente <code>grant_types_supported: [&quot;authorization_code&quot;]</code>. Em máquina sem navegador, use <a href=\"#mcp-cliente-claude-code\">Claude Code</a> (que aceita colar a URL do callback) ou faça o login em uma máquina com navegador.</p>\n<p>Veja também <a href=\"#mcp-problemas\">Solução de problemas</a>.</p>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-ferramentas\" x-show=\"bate($el.textContent)\">\n<h2>Referência das tools do MCP</h2>\n<div class=\"callout\"><div><p>Este arquivo é <strong>gerado</strong> a partir do código (<code>npm run docs:mcp-tools</code>). Não edite à mão: altere as definições em <code>src/mcp/tools/</code> e gere de novo. O CI pode rodar <code>npm run docs:mcp-tools:check</code> para detectar documentação desatualizada.</p>\n</div></div>\n<p>O servidor MCP expõe <strong>30 tools</strong>, todas com o prefixo <code>apienvios_</code>. Cada tool chama internamente a rota REST equivalente, com o mesmo JWT do login (mesmo escopo de conta, mesmas regras de papel, mesmo anti-flood). As descrições abaixo são exatamente as enviadas ao modelo (no código, em português).</p>\n<p>Convenções:</p>\n<ul>\n<li>Resposta de toda tool: um JSON em texto com <code>statusCode</code> e <code>body</code> da rota REST. Erros mantêm a semântica HTTP (por exemplo <code>401</code>, <code>403</code>, <code>404</code>, <code>429</code>). A única exceção é <code>apienvios_get_inbound_media</code>, que devolve a imagem quando a mídia é imagem ou figurinha.</li>\n<li>Tools destrutivas exigem <code>confirm: true</code>. O assistente deve pedir confirmação ao humano antes de enviar <code>true</code>.</li>\n<li>Papéis: um <strong>MEMBER</strong> só enxerga as instâncias das quais é dono; <strong>OWNER</strong> e <strong>SUPER_ADMIN</strong> enxergam a conta. As tools de membros exigem OWNER ou SUPER_ADMIN.</li>\n</ul>\n<h3 id=\"mcp-ferramentas-resumo\" style=\"margin-top:20px\">Resumo</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Tool</th>\n<th>Rota REST</th>\n<th>Guarda</th>\n<th align=\"center\">Destrutiva</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>apienvios_send_message</code></td>\n<td><code>POST /v1/messages</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_get_message</code></td>\n<td><code>GET /v1/messages/:id</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_list_messages</code></td>\n<td><code>GET /v1/messages</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_resend_message</code></td>\n<td><code>POST /v1/messages/:id/resend</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_delete_message</code></td>\n<td><code>DELETE /v1/messages/:id</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">sim</td>\n</tr>\n<tr>\n<td><code>apienvios_list_inbound_messages</code></td>\n<td><code>GET /v1/inbound-messages</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_wait_inbound_messages</code></td>\n<td><code>GET /v1/inbound-messages/wait</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_get_inbound_media</code></td>\n<td><code>GET /v1/inbound-messages/:id/media</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_transcribe_inbound_audio</code></td>\n<td><code>POST /v1/inbound-messages/:id/transcribe</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_list_instances</code></td>\n<td><code>GET /v1/instances</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_get_instance</code></td>\n<td><code>GET /v1/instances/:id</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_instances_stats</code></td>\n<td><code>GET /v1/instances/stats</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_create_instance</code></td>\n<td><code>POST /v1/instances</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_update_instance</code></td>\n<td><code>PATCH /v1/instances/:id</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_delete_instance</code></td>\n<td><code>DELETE /v1/instances/:id</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">sim</td>\n</tr>\n<tr>\n<td><code>apienvios_connect_instance</code></td>\n<td><code>POST /v1/instances/:id/connect</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_get_instance_qr</code></td>\n<td><code>GET /v1/instances/:id/qr</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_get_instance_status</code></td>\n<td><code>GET /v1/instances/:id/status</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_rotate_instance</code></td>\n<td><code>POST /v1/instances/:id/rotate</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_create_campaign</code></td>\n<td><code>POST /v1/campaigns</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_list_campaigns</code></td>\n<td><code>GET /v1/campaigns</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_get_campaign</code></td>\n<td><code>GET /v1/campaigns/:id</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_list_webhooks</code></td>\n<td><code>GET /v1/webhooks</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_create_webhook</code></td>\n<td><code>POST /v1/webhooks</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_delete_webhook</code></td>\n<td><code>DELETE /v1/webhooks/:id</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">sim</td>\n</tr>\n<tr>\n<td><code>apienvios_metrics</code></td>\n<td><code>GET /v1/metrics</code></td>\n<td><code>authManage</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_list_members</code></td>\n<td><code>GET /v1/account/users</code></td>\n<td><code>authJwt + requireOwner</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_create_member</code></td>\n<td><code>POST /v1/account/users</code></td>\n<td><code>authJwt + requireOwner</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_update_member</code></td>\n<td><code>PATCH /v1/account/users/:id</code></td>\n<td><code>authJwt + requireOwner</code></td>\n<td align=\"center\">não</td>\n</tr>\n<tr>\n<td><code>apienvios_delete_member</code></td>\n<td><code>DELETE /v1/account/users/:id</code></td>\n<td><code>authJwt + requireOwner</code></td>\n<td align=\"center\">sim</td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-ferramentas-mensagens-enviadas-e-recebidas\" style=\"margin-top:20px\">Mensagens enviadas e recebidas</h3>\n<h4 id=\"mcp-ferramentas-apienviossendmessage\" style=\"margin-top:20px\"><code>apienvios_send_message</code></h4>\n<p>Envia uma mensagem de WhatsApp de verdade (ou agenda, se scheduledAt informado). Respeita o teto anti-flood por destinatário e a posse da instância — se estourar o limite, devolve 429; se a instância não pertencer ao usuário (MEMBER), devolve 404.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>to</code></td>\n<td>string (min 10, max 20)</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td>Telefone destino, com DDI (ex.: 5544999990000)</td>\n</tr>\n<tr>\n<td><code>type</code></td>\n<td>enum: <code>TEXT</code>, <code>IMAGE</code>, <code>VIDEO</code>, <code>AUDIO</code>, <code>DOCUMENT</code>, <code>STICKER</code>, <code>BUTTONS</code>, <code>LOCATION</code>, <code>CONTACT</code>, <code>POLL</code>, <code>LIST</code></td>\n<td align=\"center\">não</td>\n<td><code>&quot;TEXT&quot;</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>text</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Texto (obrigatório se type=TEXT ou BUTTONS)</td>\n</tr>\n<tr>\n<td><code>mediaUrl</code></td>\n<td>string (URL)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>URL da mídia (obrigatório pra IMAGE/VIDEO/AUDIO/DOCUMENT/STICKER)</td>\n</tr>\n<tr>\n<td><code>caption</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>instanceId</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>ID ou slug da instância; se omitido, a conta escolhe automaticamente</td>\n</tr>\n<tr>\n<td><code>externalId</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>ID pra idempotência — reenviar com o mesmo externalId não duplica</td>\n</tr>\n<tr>\n<td><code>scheduledAt</code></td>\n<td>string (ISO 8601)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>ISO 8601 — se informado, agenda em vez de enviar imediatamente</td>\n</tr>\n<tr>\n<td><code>extra</code></td>\n<td>objeto</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Campos extras exigidos por tipos especiais (buttons/location/contact/poll/list) — ver documentação da API</td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosgetmessage\" style=\"margin-top:20px\"><code>apienvios_get_message</code></h4>\n<p>Detalhe de uma mensagem (status, tentativas de envio) — escopado à conta/MEMBER autenticado.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienvioslistmessages\" style=\"margin-top:20px\"><code>apienvios_list_messages</code></h4>\n<p>Lista mensagens da conta (ou só do MEMBER autenticado), com filtro opcional por status e paginação.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>status</code></td>\n<td>enum: <code>QUEUED</code>, <code>SENDING</code>, <code>SENT</code>, <code>DELIVERED</code>, <code>READ</code>, <code>FAILED</code>, <code>SCHEDULED</code>, <code>CANCELLED</code></td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>page</code></td>\n<td>inteiro (min 1)</td>\n<td align=\"center\">não</td>\n<td><code>1</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>limit</code></td>\n<td>inteiro (min 1, max 100)</td>\n<td align=\"center\">não</td>\n<td><code>20</code></td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosresendmessage\" style=\"margin-top:20px\"><code>apienvios_resend_message</code></h4>\n<p>Reenfileira uma mensagem que falhou (status FAILED) ou que ficou travada em SENDING sem job na fila.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosdeletemessage\" style=\"margin-top:20px\"><code>apienvios_delete_message</code></h4>\n<p>Remove uma mensagem do histórico (e tenta remover o job da fila, best-effort). Ação destrutiva — exige confirm:true (confirme com o usuário antes de chamar).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>confirm</code></td>\n<td>literal <code>true</code></td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td>Precisa ser true — confirme com o usuário antes de chamar esta tool</td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienvioslistinboundmessages\" style=\"margin-top:20px\"><code>apienvios_list_inbound_messages</code></h4>\n<p>Lista mensagens RECEBIDAS (cliente respondendo no WhatsApp) — polling, não é tempo real. Use pra checar se alguém te mandou algo desde a última checagem.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>instanceId</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Filtra por uma instância específica</td>\n</tr>\n<tr>\n<td><code>page</code></td>\n<td>inteiro (min 1)</td>\n<td align=\"center\">não</td>\n<td><code>1</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>limit</code></td>\n<td>inteiro (min 1, max 100)</td>\n<td align=\"center\">não</td>\n<td><code>20</code></td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienvioswaitinboundmessages\" style=\"margin-top:20px\"><code>apienvios_wait_inbound_messages</code></h4>\n<p>Espera (long-poll, até ~20s) chegar mensagem RECEBIDA nova e devolve NA HORA que ela chega — resposta em ~1s, sem polling. Passe em <code>since</code> o <code>nextSince</code> da resposta anterior (na 1ª chamada omita). Se <code>timedOut</code> vier true e <code>data</code> vazio, nada chegou: chame de novo com o <code>nextSince</code> devolvido.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>since</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Cursor ISO 8601: só mensagens criadas depois disso. Use o nextSince da chamada anterior; omita na primeira.</td>\n</tr>\n<tr>\n<td><code>instanceId</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Filtra por uma instância específica</td>\n</tr>\n<tr>\n<td><code>timeoutSec</code></td>\n<td>inteiro (min 1, max 25)</td>\n<td align=\"center\">não</td>\n<td><code>20</code></td>\n<td>Máximo de segundos que a chamada espera antes de devolver vazio</td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosgetinboundmedia\" style=\"margin-top:20px\"><code>apienvios_get_inbound_media</code></h4>\n<p>Baixa a mídia de uma mensagem RECEBIDA (use o <code>id</code> e o <code>mediaType</code> vindos de list/wait). Imagem e figurinha voltam como imagem pra você enxergar. Áudio do próprio dono já vem transcrito em <code>text</code>; para áudio sem <code>text</code> use apienvios_transcribe_inbound_audio.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td>id da mensagem recebida (campo <code>id</code> do list/wait)</td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviostranscribeinboundaudio\" style=\"margin-top:20px\"><code>apienvios_transcribe_inbound_audio</code></h4>\n<p>Transcreve UM áudio recebido que veio sem <code>text</code> (áudio de outro número, não transcrito automaticamente). Use só para áudio de um chat que você está autorizado a responder. Devolve a transcrição.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td>id da mensagem de áudio recebida (campo <code>id</code> do list/wait)</td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-ferramentas-instâncias-números-de-whatsapp\" style=\"margin-top:20px\">Instâncias (números de WhatsApp)</h3>\n<h4 id=\"mcp-ferramentas-apienvioslistinstances\" style=\"margin-top:20px\"><code>apienvios_list_instances</code></h4>\n<p>Lista as instâncias (números de WhatsApp) da conta — se MEMBER, só as próprias.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>page</code></td>\n<td>inteiro (min 1)</td>\n<td align=\"center\">não</td>\n<td><code>1</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>limit</code></td>\n<td>inteiro (min 1, max 100)</td>\n<td align=\"center\">não</td>\n<td><code>20</code></td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosgetinstance\" style=\"margin-top:20px\"><code>apienvios_get_instance</code></h4>\n<p>Detalhe de uma instância (id ou slug).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosinstancesstats\" style=\"margin-top:20px\"><code>apienvios_instances_stats</code></h4>\n<p>Estatísticas agregadas das instâncias da conta (contagem por status/provider).</p>\n<p>Sem parâmetros.</p>\n<h4 id=\"mcp-ferramentas-apienvioscreateinstance\" style=\"margin-top:20px\"><code>apienvios_create_instance</code></h4>\n<p>Cria uma nova instância (número de WhatsApp) — respeita a cota maxInstances da conta.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>provider</code></td>\n<td>enum: <code>EVOLUTION</code>, <code>WUZAPI</code>, <code>CLOUD_API</code></td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>name</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>slug</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>priority</code></td>\n<td>inteiro (min 0)</td>\n<td align=\"center\">não</td>\n<td><code>0</code></td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosupdateinstance\" style=\"margin-top:20px\"><code>apienvios_update_instance</code></h4>\n<p>Renomeia uma instância (name e/ou slug — ao menos um obrigatório).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>name</code></td>\n<td>string (min 1)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>slug</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosdeleteinstance\" style=\"margin-top:20px\"><code>apienvios_delete_instance</code></h4>\n<p>Apaga uma instância (cascata: números, mensagens associadas). Ação destrutiva — exige confirm:true (confirme com o usuário antes de chamar).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>confirm</code></td>\n<td>literal <code>true</code></td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td>Precisa ser true — confirme com o usuário antes de chamar esta tool</td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosconnectinstance\" style=\"margin-top:20px\"><code>apienvios_connect_instance</code></h4>\n<p>Inicia a conexão de uma instância (gera QR code pra escanear, dependendo do provider).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosgetinstanceqr\" style=\"margin-top:20px\"><code>apienvios_get_instance_qr</code></h4>\n<p>QR code atual da instância (string, geralmente data-URL) pra parear o WhatsApp.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosgetinstancestatus\" style=\"margin-top:20px\"><code>apienvios_get_instance_status</code></h4>\n<p>Status de conexão atual da instância (sincroniza com o provider antes de responder).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosrotateinstance\" style=\"margin-top:20px\"><code>apienvios_rotate_instance</code></h4>\n<p>Força a rotação/reconexão de uma instância (novo QR, desconecta a sessão atual do provider).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-ferramentas-campanhas-envio-em-lote\" style=\"margin-top:20px\">Campanhas (envio em lote)</h3>\n<h4 id=\"mcp-ferramentas-apienvioscreatecampaign\" style=\"margin-top:20px\"><code>apienvios_create_campaign</code></h4>\n<p>Dispara uma mensagem em lote pra até 1000 destinatários. Reusa a mesma fila e anti-flood do envio individual — cada destinatário pode ficar RATE_LIMITED se estourar o teto.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>to</code></td>\n<td>lista de string (min 10, max 20) (min 1, max 1000)</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>type</code></td>\n<td>enum: <code>TEXT</code>, <code>IMAGE</code>, <code>VIDEO</code>, <code>AUDIO</code>, <code>DOCUMENT</code></td>\n<td align=\"center\">não</td>\n<td><code>&quot;TEXT&quot;</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>text</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>mediaUrl</code></td>\n<td>string (URL)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>caption</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>instanceId</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>name</code></td>\n<td>string (max 120)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Rótulo do lote, aparece no monitor</td>\n</tr>\n<tr>\n<td><code>externalIdPrefix</code></td>\n<td>string (max 80)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Prefixo pra idempotência por destino</td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienvioslistcampaigns\" style=\"margin-top:20px\"><code>apienvios_list_campaigns</code></h4>\n<p>Lista campanhas com progresso agregado (escopado ao MEMBER se aplicável).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>limit</code></td>\n<td>inteiro (min 1, max 50)</td>\n<td align=\"center\">não</td>\n<td><code>20</code></td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosgetcampaign\" style=\"margin-top:20px\"><code>apienvios_get_campaign</code></h4>\n<p>Progresso detalhado de uma campanha (contagem por status: enviado/falho/na fila).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-ferramentas-webhooks\" style=\"margin-top:20px\">Webhooks</h3>\n<h4 id=\"mcp-ferramentas-apienvioslistwebhooks\" style=\"margin-top:20px\"><code>apienvios_list_webhooks</code></h4>\n<p>Lista os webhooks cadastrados na conta.</p>\n<p>Sem parâmetros.</p>\n<h4 id=\"mcp-ferramentas-apienvioscreatewebhook\" style=\"margin-top:20px\"><code>apienvios_create_webhook</code></h4>\n<p>Cadastra um webhook. A URL é validada contra SSRF (rejeita IP privado/loopback/metadata da nuvem).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>url</code></td>\n<td>string (URL)</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>events</code></td>\n<td>lista de enum: <code>BAN_DETECTED</code>, <code>NUMBER_ROTATED</code>, <code>NUMBER_DISCONNECTED</code>, <code>MESSAGE_FAILED</code>, <code>MESSAGE_DELIVERED</code>, <code>MESSAGE_RECEIVED</code>, <code>PROVIDER_DOWN</code> (min 1)</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>secret</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td>Segredo pra assinar/autenticar a entrega (?ws=)</td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosdeletewebhook\" style=\"margin-top:20px\"><code>apienvios_delete_webhook</code></h4>\n<p>Remove um webhook da conta. Ação destrutiva — exige confirm:true (confirme com o usuário antes de chamar).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>confirm</code></td>\n<td>literal <code>true</code></td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td>Precisa ser true — confirme com o usuário antes de chamar esta tool</td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-ferramentas-métricas\" style=\"margin-top:20px\">Métricas</h3>\n<h4 id=\"mcp-ferramentas-apienviosmetrics\" style=\"margin-top:20px\"><code>apienvios_metrics</code></h4>\n<p>Métricas de envio da conta: totais, série diária, por instância/número.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>days</code></td>\n<td>inteiro (min 1, max 90)</td>\n<td align=\"center\">não</td>\n<td><code>7</code></td>\n<td></td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-ferramentas-membros-da-conta\" style=\"margin-top:20px\">Membros da conta</h3>\n<h4 id=\"mcp-ferramentas-apienvioslistmembers\" style=\"margin-top:20px\"><code>apienvios_list_members</code></h4>\n<p>Lista os MEMBERs (usuários) da conta — exige ser OWNER ou SUPER_ADMIN.</p>\n<p>Sem parâmetros.</p>\n<h4 id=\"mcp-ferramentas-apienvioscreatemember\" style=\"margin-top:20px\"><code>apienvios_create_member</code></h4>\n<p>Cria um MEMBER na própria conta (login local com e-mail e senha).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>email</code></td>\n<td>string (e-mail)</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>password</code></td>\n<td>string (min 8)</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>name</code></td>\n<td>string</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosupdatemember\" style=\"margin-top:20px\"><code>apienvios_update_member</code></h4>\n<p>Atualiza nome e/ou senha de um MEMBER da própria conta.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>name</code></td>\n<td>string (min 1)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>password</code></td>\n<td>string (min 8)</td>\n<td align=\"center\">não</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<h4 id=\"mcp-ferramentas-apienviosdeletemember\" style=\"margin-top:20px\"><code>apienvios_delete_member</code></h4>\n<p>Remove um MEMBER da própria conta. Ação destrutiva — exige confirm:true (confirme com o usuário antes de chamar).</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Parâmetro</th>\n<th>Tipo</th>\n<th align=\"center\">Obrigatório</th>\n<th>Padrão</th>\n<th>Descrição</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>id</code></td>\n<td>string</td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td></td>\n</tr>\n<tr>\n<td><code>confirm</code></td>\n<td>literal <code>true</code></td>\n<td align=\"center\">sim</td>\n<td>—</td>\n<td>Precisa ser true — confirme com o usuário antes de chamar esta tool</td>\n</tr>\n</tbody></table>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-seguranca\" x-show=\"bate($el.textContent)\">\n<h2>Segurança do MCP</h2>\n<p>Este documento descreve a superfície do servidor MCP, o que ele protege, as diferenças conhecidas em relação à especificação atual do MCP e as boas práticas de uso. O modelo de segurança geral do projeto está em <code>../security.md</code>. Para reportar vulnerabilidades, veja <code>../../SECURITY.md</code>.</p>\n<h3 id=\"mcp-seguranca-superfície-exposta\" style=\"margin-top:20px\">Superfície exposta</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Endpoint</th>\n<th align=\"center\">Autenticado</th>\n<th>Observação</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>GET /.well-known/oauth-*</code></td>\n<td align=\"center\">não</td>\n<td>Metadados públicos de descoberta</td>\n</tr>\n<tr>\n<td><code>POST /mcp/oauth/register</code></td>\n<td align=\"center\">não</td>\n<td>Dynamic Client Registration aberto (padrão do fluxo). Sujeito ao rate limit global por IP</td>\n</tr>\n<tr>\n<td><code>GET/POST /mcp/oauth/authorize</code></td>\n<td align=\"center\">não (é o login)</td>\n<td>Proteção própria contra força bruta em 3 camadas; fora do rate limit global de propósito</td>\n</tr>\n<tr>\n<td><code>POST /mcp/oauth/token</code></td>\n<td align=\"center\">código de uso único + PKCE</td>\n<td>Resposta de erro única (<code>invalid_grant</code>) para qualquer falha</td>\n</tr>\n<tr>\n<td><code>POST /mcp</code></td>\n<td align=\"center\">sim (JWT)</td>\n<td>Todas as tools. 401 com <code>WWW-Authenticate</code> quando não autenticado</td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-seguranca-o-que-o-servidor-protege\" style=\"margin-top:20px\">O que o servidor protege</h3>\n<ul>\n<li><strong>PKCE S256 obrigatório.</strong> <code>plain</code> é rejeitado.</li>\n<li><strong>Código de autorização</strong> de uso único, válido por 90 segundos. É apagado ao ser lido, mesmo se o PKCE falhar.</li>\n<li><strong>Validação do <code>redirect_uri</code>:</strong> só <code>https://</code> ou <code>http://localhost</code> / <code>127.0.0.1</code>, e precisa ser exatamente um dos registrados. Parâmetros inválidos retornam 400 sem redirecionar (sem open redirect).</li>\n<li><strong>Parâmetros de autorização fora do formulário.</strong> O formulário carrega só uma chave opaca guardada no Redis, não <code>code_challenge</code> nem <code>redirect_uri</code> em campos ocultos.</li>\n<li><strong>CSP restrita.</strong> O formulário de login permite no <code>form-action</code> apenas a origem do <code>redirect_uri</code> já validado.</li>\n<li><strong>Isolamento por conta.</strong> Cada tool chama a rota REST com o JWT do usuário; o escopo (conta, MEMBER) é decidido pela rota, nunca pela camada MCP.</li>\n<li><strong>Tools destrutivas exigem <code>confirm: true</code>.</strong></li>\n<li><strong>Webhooks criados por MCP</strong> passam pela validação contra SSRF (IPs privados, loopback e metadados de nuvem são rejeitados).</li>\n</ul>\n<h3 id=\"mcp-seguranca-o-token-do-mcp-é-uma-sessão-completa\" style=\"margin-top:20px\">O token do MCP é uma sessão completa</h3>\n<p>O <code>access_token</code> é o <strong>mesmo JWT do painel</strong>. Quem o possui tem as permissões do usuário que fez login, enquanto a sessão estiver viva, e o mesmo JWT também é aceito pelas rotas REST (<code>Authorization: Bearer</code>). Trate-o como uma senha de sessão:</p>\n<ul>\n<li>Não cole o JWT, nem a URL de callback com <code>code=...</code>, em chats públicos, issues ou logs.</li>\n<li>Sessões morrem por inatividade (<code>SESSION_IDLE_TIMEOUT_MIN</code>, padrão 30 minutos), por logout e ao excluir o usuário.</li>\n<li>Para derrubar <strong>todas</strong> as sessões de uma vez, troque <code>JWT_SECRET</code> e reinicie.</li>\n</ul>\n<h3 id=\"mcp-seguranca-diferenças-conhecidas-em-relação-à-especificação-do-mcp\" style=\"margin-top:20px\">Diferenças conhecidas em relação à especificação do MCP</h3>\n<p>Comparação feita com a especificação de autorização do MCP lida em 2026-10-06 (versão <code>2026-07-28</code>). A especificação evolui; confira a versão atual.</p>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Item da especificação</th>\n<th>Este servidor</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>PKCE</td>\n<td>Implementado (S256)</td>\n</tr>\n<tr>\n<td>Protected Resource Metadata (RFC 9728) e <code>WWW-Authenticate</code> com <code>resource_metadata</code></td>\n<td>Implementado</td>\n</tr>\n<tr>\n<td>Authorization Server Metadata (RFC 8414)</td>\n<td>Implementado</td>\n</tr>\n<tr>\n<td>Dynamic Client Registration (RFC 7591)</td>\n<td>Implementado (a especificação o trata como legado, mantido por compatibilidade)</td>\n</tr>\n<tr>\n<td>Client ID Metadata Documents (a especificação recomenda)</td>\n<td><strong>Não implementado</strong>. Clientes que só usam esse mecanismo não conseguem se registrar</td>\n</tr>\n<tr>\n<td>Parâmetro <code>resource</code> (RFC 8707)</td>\n<td>Aceito e guardado junto ao código, mas <strong>o token não é amarrado a essa audiência</strong>. O JWT não tem claim de audiência</td>\n</tr>\n<tr>\n<td>Validação de audiência do token no recurso</td>\n<td><strong>Não implementada</strong>: o token é o JWT de sessão do painel</td>\n</tr>\n<tr>\n<td><code>iss</code> na resposta de autorização (RFC 9207)</td>\n<td><strong>Não enviado</strong> (e <code>authorization_response_iss_parameter_supported</code> não é anunciado)</td>\n</tr>\n<tr>\n<td>Refresh token</td>\n<td><strong>Não emitido</strong>. Ao fim da sessão, novo login</td>\n</tr>\n<tr>\n<td>Escopos</td>\n<td><code>scope: &quot;mcp&quot;</code> fixo, apenas informativo. Não há escopos granulares por tool; o controle é por papel do usuário</td>\n</tr>\n</tbody></table>\n<p>Essas diferenças são limites desta versão (<code>0.1.0</code>), não segredos. Se o seu modelo de ameaça exige audiência amarrada ao token ou escopos por tool, trate como trabalho a fazer antes de expor o MCP a clientes que você não controla.</p>\n<h3 id=\"mcp-seguranca-boas-práticas\" style=\"margin-top:20px\">Boas práticas</h3>\n<ol>\n<li><strong>HTTPS sempre</strong>, com <code>PUBLIC_API_URL</code> correto. Não exponha o servidor em HTTP puro.</li>\n<li><strong>Menor privilégio:</strong> conecte o assistente com um usuário <strong>MEMBER</strong>, dono apenas das instâncias necessárias. Evite usar a conta OWNER ou SUPER_ADMIN para uso rotineiro de assistentes.</li>\n<li><strong>Bloqueie tools destrutivas no cliente.</strong> Muitos clientes permitem lista de tools desabilitadas ou aprovação manual (por exemplo, <code>disabled_tools</code> no <a href=\"#mcp-cliente-codex\">Codex</a>). Não use aprovação automática para <code>apienvios_delete_*</code>.</li>\n<li><strong>Mensagens recebidas são entrada não confiável.</strong> Um contato mal-intencionado pode escrever instruções no WhatsApp para enganar o modelo (injeção de prompt). O texto da ponte manda o assistente ignorar isso, mas é uma defesa em nível de modelo, não uma barreira técnica. A barreira real é o menor privilégio e a confirmação humana para ações destrutivas. Se você não precisa da ponte, defina <code>MCP_BRIDGE_ENABLED=false</code>.</li>\n<li><strong>Sessão curta:</strong> reduza <code>SESSION_IDLE_TIMEOUT_MIN</code> se o assistente ficar em máquinas compartilhadas.</li>\n<li><strong>Proxy reverso correto:</strong> repasse o IP real do cliente (o servidor só confia em <code>X-Forwarded-For</code> quando o salto imediato é uma faixa privada), senão o rate limit por IP junta todos os usuários.</li>\n<li><strong>Revise as aprovações</strong> que o cliente pede antes de rodar tools de escrita (envio em lote, criação de webhook, gestão de membros).</li>\n</ol>\n<h3 id=\"mcp-seguranca-o-que-não-expor\" style=\"margin-top:20px\">O que não expor</h3>\n<ul>\n<li><code>JWT_SECRET</code>, <code>API_SECRET</code>, <code>SECRETS_ENCRYPTION_KEY</code>, <code>GEMINI_API_KEY</code>, senhas de banco e tokens de provedores.</li>\n<li>Arquivos de configuração de cliente com cabeçalhos de autorização, em repositórios (por exemplo, <code>.mcp.json</code> com <code>headers</code>). Neste servidor você nem precisa deles: o login é por OAuth.</li>\n<li>JWT de sessão, URLs de callback com <code>code=</code> e prints do terminal que os mostrem.</li>\n<li>Dados de outras contas: se uma tool devolver algo que não é da conta do usuário, é um bug de isolamento; reporte conforme <code>../../SECURITY.md</code>.</li>\n</ul>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-problemas\" x-show=\"bate($el.textContent)\">\n<h2>Solução de problemas do MCP</h2>\n<h3 id=\"mcp-problemas-login-e-autorização\" style=\"margin-top:20px\">Login e autorização</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Sintoma</th>\n<th>Causa e solução</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>O cliente pede novo login depois de cerca de 30 minutos, mesmo com uso contínuo</td>\n<td>O <code>expires_in</code> anunciado precisa ser a <strong>vida real do JWT</strong> (<code>JWT_EXPIRES_IN</code>), não o tempo de inatividade. Clientes tratam <code>expires_in</code> como validade fixa e, sem <code>refresh_token</code>, exigem novo login quando ele acaba. Este servidor calcula <code>expires_in</code> como <code>exp - iat</code> do JWT. Se você alterou esse trecho, restaure o cálculo</td>\n</tr>\n<tr>\n<td>O formulário de login é enviado, mas a página fica parada</td>\n<td>Navegadores baseados em Chromium aplicam o <code>form-action</code> da CSP também ao <strong>redirecionamento</strong> que vem depois do POST. A resposta HTML do <code>/authorize</code> precisa liberar a origem do <code>redirect_uri</code> já validado (o servidor faz isso). Verifique se o seu proxy reverso não sobrescreve o cabeçalho <code>Content-Security-Policy</code>. No console do navegador, procure &quot;Refused to send form data&quot;</td>\n</tr>\n<tr>\n<td><code>http://localhost:&lt;porta&gt;/callback</code> não carrega</td>\n<td>Esperado quando o cliente roda em máquina remota. Copie a URL <strong>completa</strong> da barra de endereço e cole no cliente (veja <a href=\"#mcp-cliente-claude-code\">Guia: Claude Code</a>)</td>\n</tr>\n<tr>\n<td>&quot;No OAuth flow is in progress&quot; ao colar a URL</td>\n<td>Cada novo login invalida o link e o código anteriores. Refaça o login e cole a URL da <strong>última</strong> tentativa, sem abrir outro login no meio</td>\n</tr>\n<tr>\n<td><code>Sessão de autorização expirada. Tente conectar novamente</code></td>\n<td>Os parâmetros do <code>/authorize</code> vivem 30 minutos e o formulário só vale uma vez. Recomece pela tela de conexão do cliente</td>\n</tr>\n<tr>\n<td><code>Parâmetros OAuth inválidos ou ausentes</code> (400)</td>\n<td>O cliente não enviou <code>code_challenge_method=S256</code>, ou o <code>code_challenge</code> tem tamanho fora de 43 a 128, ou o <code>redirect_uri</code> não é <code>https://</code> nem <code>http://localhost</code></td>\n</tr>\n<tr>\n<td><code>Client não registrado ou redirect_uri não corresponde</code> (400)</td>\n<td>O cliente guardou um <code>client_id</code> que o servidor não conhece mais (Redis esvaziado ou registro com mais de 180 dias). Remova o servidor do cliente e adicione de novo para registrar outra vez</td>\n</tr>\n<tr>\n<td><code>invalid_grant</code> no <code>/token</code></td>\n<td>Mesma resposta para qualquer falha: código expirado (90 s), já usado, <code>client_id</code> ou <code>redirect_uri</code> diferentes dos da autorização, ou <code>code_verifier</code> que não confere. Refaça o login</td>\n</tr>\n<tr>\n<td><code>Muitas tentativas. Tente novamente em N min.</code> (429 no login)</td>\n<td>Proteção contra força bruta: 5 falhas por 15 min por IP + conta, 20 por IP, 20 por dispositivo. Espere ou, em ambiente de teste, ajuste <code>LOGIN_*</code> (veja <code>../configuration.md</code>)</td>\n</tr>\n<tr>\n<td><code>Credenciais inválidas.</code></td>\n<td>E-mail ou senha incorretos. O login MCP usa a mesma verificação do painel</td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-problemas-depois-de-conectado\" style=\"margin-top:20px\">Depois de conectado</h3>\n<table class=\"instances-table\">\n<thead>\n<tr>\n<th>Sintoma</th>\n<th>Causa e solução</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>401 Sessão expirada. Faça login novamente.</code></td>\n<td>Passou mais que <code>SESSION_IDLE_TIMEOUT_MIN</code> sem nenhuma chamada, ou houve logout. Refaça o login (o <code>WWW-Authenticate</code> aponta para os metadados)</td>\n</tr>\n<tr>\n<td><code>401 Token inválido ou expirado</code></td>\n<td>JWT adulterado, expirado, ou <code>JWT_SECRET</code> mudou. Refaça o login</td>\n</tr>\n<tr>\n<td><code>401 Usuário ou conta inválidos/inativos</code></td>\n<td>O usuário foi removido ou a conta foi desativada</td>\n</tr>\n<tr>\n<td>As tools não aparecem depois do <code>/mcp</code> mostrar &quot;Authentication successful&quot;</td>\n<td>Alguns clientes só carregam a lista de tools no início da sessão. Reinicie ou retome a sessão do cliente (no Claude Code, <code>claude --continue</code>). Observação de prática, não de documentação oficial</td>\n</tr>\n<tr>\n<td><code>404</code> em uma instância que existe</td>\n<td>Um MEMBER só enxerga as instâncias das quais é dono. Peça ao OWNER para atribuir a instância</td>\n</tr>\n<tr>\n<td><code>403</code> nas tools de membros</td>\n<td>Exigem papel OWNER ou SUPER_ADMIN</td>\n</tr>\n<tr>\n<td><code>429 Rate limit excedido para este cliente</code></td>\n<td>Teto de requisições por minuto (<code>DEFAULT_RATE_LIMIT</code>, balde por IP). Reduza o ritmo do assistente. Atrás de proxy, confira se o IP real do cliente chega ao app</td>\n</tr>\n<tr>\n<td><code>429</code> ao enviar mensagem, com <code>Retry-After</code></td>\n<td>Limite de envios ao mesmo destinatário por hora (padrão 10 por conta). Espere o tempo indicado</td>\n</tr>\n<tr>\n<td><code>GET /mcp</code> devolve 404</td>\n<td>Esperado: o endpoint é sem estado e só aceita <code>POST</code></td>\n</tr>\n<tr>\n<td>Falha de descoberta atrás de proxy</td>\n<td>Confirme que <code>PUBLIC_API_URL</code> é a URL HTTPS pública e que <code>/.well-known/*</code>, <code>/mcp</code> e <code>/mcp/oauth/*</code> chegam ao app. Teste: <code>curl __MCP_API_BASE__/.well-known/oauth-authorization-server</code></td>\n</tr>\n</tbody></table>\n<h3 id=\"mcp-problemas-teste-de-ponta-a-ponta-sem-cliente\" style=\"margin-top:20px\">Teste de ponta a ponta sem cliente</h3>\n<div class=\"code\" x-data=\"{ copied:false }\"><button type=\"button\" class=\"code-copy\" @click=\"navigator.clipboard.writeText($refs.c.innerText); copied=true; setTimeout(()=>copied=false,1500)\" x-text=\"copied?'Copiado!':'Copiar'\"></button><pre x-ref=\"c\"><code># 1. Sem token: deve responder 401 com o cabeçalho WWW-Authenticate\ncurl -i -X POST __MCP_API_BASE__/mcp -H &#39;Content-Type: application/json&#39; \\\n  -H &#39;Accept: application/json, text/event-stream&#39; \\\n  -d &#39;{&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:1,&quot;method&quot;:&quot;initialize&quot;,&quot;params&quot;:{&quot;protocolVersion&quot;:&quot;2025-03-26&quot;,&quot;capabilities&quot;:{},&quot;clientInfo&quot;:{&quot;name&quot;:&quot;teste&quot;,&quot;version&quot;:&quot;0&quot;}}}&#39;\n\n# 2. Metadados de descoberta\ncurl -s __MCP_API_BASE__/.well-known/oauth-protected-resource/mcp\ncurl -s __MCP_API_BASE__/.well-known/oauth-authorization-server</code></pre></div>\n<p>Se o item 1 não trouxer <code>WWW-Authenticate: Bearer resource_metadata=...</code>, o proxy está removendo o cabeçalho.</p>\n<h3 id=\"mcp-problemas-problemas-por-cliente\" style=\"margin-top:20px\">Problemas por cliente</h3>\n<p>Cada guia em <a href=\"#mcp-conectar\">clients/</a> tem os pontos específicos do cliente. Em resumo:</p>\n<ul>\n<li><strong>Claude Code:</strong> máquina remota, porta de callback e retomada da sessão (<a href=\"#mcp-cliente-claude-code\">Guia: Claude Code</a>).</li>\n<li><strong>claude.ai:</strong> o servidor precisa ser público; escolha a opção de registro automático se a recomendada falhar (<a href=\"#mcp-cliente-claude-ai-desktop\">Guia: claude.ai e Desktop</a>).</li>\n<li><strong>Cursor:</strong> não faz DCR; use o cliente registrado à mão ou o <code>mcp-remote</code> (<a href=\"#mcp-cliente-cursor\">Guia: Cursor</a>).</li>\n<li><strong>Gemini CLI:</strong> exige navegador local (<a href=\"#mcp-cliente-gemini-cli\">Guia: Gemini CLI</a>).</li>\n<li><strong>Clientes sem OAuth:</strong> use o <a href=\"#mcp-cliente-mcp-remote\">mcp-remote</a>.</li>\n</ul>\n</div>\n\n<div class=\"card mcp-doc\" id=\"mcp-exemplos\" x-show=\"bate($el.textContent)\">\n<h2>Exemplos de uso</h2>\n<p>Pedidos em linguagem natural que o assistente converte em chamadas das tools (veja <a href=\"#mcp-ferramentas\">Ferramentas (30 tools)</a>). Os números abaixo são fictícios.</p>\n<h3 id=\"mcp-exemplos-instâncias\" style=\"margin-top:20px\">Instâncias</h3>\n<ul>\n<li>&quot;Liste as minhas instâncias e diga quais estão conectadas.&quot; (<code>apienvios_list_instances</code>, <code>apienvios_get_instance_status</code>)</li>\n<li>&quot;Crie uma instância chamada Suporte usando o provedor Evolution e gere o QR code.&quot; (<code>apienvios_create_instance</code>, <code>apienvios_connect_instance</code>, <code>apienvios_get_instance_qr</code>)</li>\n<li>&quot;Reconecte a instância suporte: ela parou de responder.&quot; (<code>apienvios_rotate_instance</code>)</li>\n<li>&quot;Quantas instâncias eu tenho por status e por provedor?&quot; (<code>apienvios_instances_stats</code>)</li>\n</ul>\n<h3 id=\"mcp-exemplos-enviar-mensagens\" style=\"margin-top:20px\">Enviar mensagens</h3>\n<ul>\n<li>&quot;Envie &#39;Olá, seu pedido saiu para entrega&#39; para 5544999990000 pela instância suporte.&quot; (<code>apienvios_send_message</code>)</li>\n<li>&quot;Agende para amanhã às 9h, no horário de Brasília, um lembrete para 5544999990000.&quot; (<code>apienvios_send_message</code> com <code>scheduledAt</code> em ISO 8601)</li>\n<li>&quot;Envie esta imagem com a legenda &#39;Cardápio de hoje&#39;: <a href=\"https://exemplo.com/cardapio.png\" target=\"_blank\" rel=\"noopener noreferrer\">https://exemplo.com/cardapio.png</a>&quot; (<code>type: IMAGE</code>, <code>mediaUrl</code>, <code>caption</code>)</li>\n<li>&quot;A mensagem abc123 falhou. Veja o motivo e tente de novo.&quot; (<code>apienvios_get_message</code>, <code>apienvios_resend_message</code>)</li>\n<li>&quot;Liste as últimas mensagens com status FAILED.&quot; (<code>apienvios_list_messages</code>)</li>\n</ul>\n<p>Botões, localização, contato, enquete e lista só funcionam com número WuzAPI (veja <code>../providers.md</code>).</p>\n<h3 id=\"mcp-exemplos-ler-respostas\" style=\"margin-top:20px\">Ler respostas</h3>\n<ul>\n<li>&quot;Tem alguma mensagem nova recebida? Resuma.&quot; (<code>apienvios_list_inbound_messages</code>)</li>\n<li>&quot;Fique aguardando a próxima mensagem do cliente e me avise.&quot; (<code>apienvios_wait_inbound_messages</code>, espera de até 20 s por chamada)</li>\n<li>&quot;Veja a imagem que o cliente mandou na mensagem xyz.&quot; (<code>apienvios_get_inbound_media</code>)</li>\n<li>&quot;Transcreva o áudio da mensagem xyz.&quot; (<code>apienvios_transcribe_inbound_audio</code>, precisa de <code>GEMINI_API_KEY</code>)</li>\n</ul>\n<h3 id=\"mcp-exemplos-campanhas-webhooks-métricas-e-equipe\" style=\"margin-top:20px\">Campanhas, webhooks, métricas e equipe</h3>\n<ul>\n<li>&quot;Dispare &#39;Promoção até sexta&#39; para estes 50 números, com prefixo de idempotência <code>promo-out</code>.&quot; (<code>apienvios_create_campaign</code>, até 1000 destinatários; cada um respeita o anti-flood)</li>\n<li>&quot;Como está o progresso da campanha tal?&quot; (<code>apienvios_get_campaign</code>)</li>\n<li>&quot;Cadastre um webhook em <a href=\"https://exemplo.com/hook\" target=\"_blank\" rel=\"noopener noreferrer\">https://exemplo.com/hook</a> para os eventos MESSAGE_FAILED e BAN_DETECTED.&quot; (<code>apienvios_create_webhook</code>)</li>\n<li>&quot;Mostre as métricas dos últimos 30 dias.&quot; (<code>apienvios_metrics</code>, até 90 dias)</li>\n<li>&quot;Crie um usuário MEMBER para ana@exemplo.com.&quot; (<code>apienvios_create_member</code>, exige OWNER ou SUPER_ADMIN)</li>\n</ul>\n<h3 id=\"mcp-exemplos-ações-destrutivas\" style=\"margin-top:20px\">Ações destrutivas</h3>\n<p>Apagar instância, mensagem, webhook ou membro exige <code>confirm: true</code>. O assistente deve pedir sua confirmação antes:</p>\n<div class=\"callout\"><div><p>Você: &quot;Apague o webhook wh_123.&quot;\nAssistente: &quot;Isso remove o webhook wh_123 da conta. Confirma?&quot;\nVocê: &quot;Confirmo.&quot;</p>\n</div></div>\n<p>Se o seu cliente permite, desabilite essas tools ou exija aprovação manual (veja <a href=\"#mcp-seguranca\">Segurança</a>).</p>\n<h3 id=\"mcp-exemplos-ponte-whatsapp\" style=\"margin-top:20px\">Ponte WhatsApp</h3>\n<p>Com a ponte ativa (padrão), mande para você mesmo, no WhatsApp, uma mensagem que comece com a palavra de ativação (padrão <code>Claude</code>), por exemplo <code>Claude, você está aí?</code>. O assistente conectado responde na mesma conversa, com o prefixo <code>Claude: </code>. Veja <a href=\"#mcp-visao-geral\">Visão geral</a>.</p>\n</div>\n"
